String _ngelxUzantiTemizle(String value) {
  final v = value.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]'), '');
  return v.isEmpty ? 'bin' : (v.length > 8 ? v.substring(0, 8) : v);
}

String _ngelxContentType(String ext) {
  switch (_ngelxUzantiTemizle(ext)) {
    case 'jpg':
    case 'jpeg':
      return 'image/jpeg';
    case 'png':
      return 'image/png';
    case 'webp':
      return 'image/webp';
    case 'gif':
      return 'image/gif';
    case 'heic':
      return 'image/heic';
    case 'heif':
      return 'image/heif';
    case 'mp4':
      return 'video/mp4';
    case 'mov':
      return 'video/quicktime';
    case 'mp3':
      return 'audio/mpeg';
    case 'm4a':
      return 'audio/mp4';
    case 'aac':
      return 'audio/aac';
    case 'wav':
      return 'audio/wav';
    case 'ogg':
      return 'audio/ogg';
    default:
      return 'application/octet-stream';
  }
}

Future<Uint8List> ngelxFotoDuzenle(Uint8List bytes,{String efekt='Yok',int donus=0,bool kareKirp=false})async{
  final turns=((donus%4)+4)%4;if(efekt=='Yok'&&turns==0&&!kareKirp)return bytes;
  final codec=await ui.instantiateImageCodec(bytes),frame=await codec.getNextFrame(),kaynak=frame.image;
  int kw=kaynak.width,kh=kaynak.height;if(kareKirp){final k=math.min(kw,kh);kw=k;kh=k;}
  final sol=(kaynak.width-kw)/2,ust=(kaynak.height-kh)/2,ow=turns.isOdd?kh:kw,oh=turns.isOdd?kw:kh;
  final rec=ui.PictureRecorder(),canvas=Canvas(rec);canvas.translate(ow/2,oh/2);canvas.rotate(turns*math.pi/2);
  final p=Paint()..filterQuality=FilterQuality.high;
  if(efekt=='Parlak')p.colorFilter=const ColorFilter.matrix([1,0,0,0,22,0,1,0,0,22,0,0,1,0,22,0,0,0,1,0]);
  if(efekt=='Sıcak')p.colorFilter=const ColorFilter.matrix([1.05,0,0,0,14,0,1.02,0,0,5,0,0,.94,0,-8,0,0,0,1,0]);
  if(efekt=='Soğuk')p.colorFilter=const ColorFilter.matrix([.95,0,0,0,-5,0,1,0,0,2,0,0,1.07,0,14,0,0,0,1,0]);
  if(efekt=='Siyah Beyaz')p.colorFilter=const ColorFilter.matrix([.299,.587,.114,0,0,.299,.587,.114,0,0,.299,.587,.114,0,0,0,0,0,1,0]);
  canvas.drawImageRect(kaynak,Rect.fromLTWH(sol,ust,kw.toDouble(),kh.toDouble()),Rect.fromCenter(center:Offset.zero,width:kw.toDouble(),height:kh.toDouble()),p);
  final res=await rec.endRecording().toImage(ow,oh),png=await res.toByteData(format:ui.ImageByteFormat.png);if(png==null)throw Exception('Fotoğraf düzenlenemedi.');return png.buffer.asUint8List();
}

int _ngelxMaksimumMedyaBoyutu(String kind) {
  switch (kind) {
    case 'videos':
      return 80 * 1024 * 1024;
    case 'profile-intros':
      return 35 * 1024 * 1024;
    case 'chat-files':
      return 30 * 1024 * 1024;
    case 'music':
    case 'chat-audio':
      return 15 * 1024 * 1024;
    case 'gifs':
      return 12 * 1024 * 1024;
    default:
      return 10 * 1024 * 1024;
  }
}

Future<String> ngelxMediaApiAdresi() async {
  // Test 237: Firestore override ve yedek endpoint bilinçli olarak devre dışı.
  // Böylece ilk gerçek hata başka fallback'ler tarafından gizlenmiyor.
  final build=_ngelxMediaApiBuild.trim().replaceAll(RegExp(r'/+$'), '');
  if(build.isEmpty)throw Exception('NgelX medya servisi yapılandırılmamış.');
  _ngelxMediaApiCache=build;
  _ngelxMediaApiCacheZamani=DateTime.now();
  return build;
}

const MethodChannel _ngelxMedyaNativeKanal=MethodChannel('com.nnentx.ngelx_app/media');

String _ngelxKisaHata(Object hata) {
  final raw=hata.toString().replaceFirst('Exception: ','').replaceAll('\n',' ').trim();
  return raw.length>320?raw.substring(0,320):raw;
}

Future<Map<String,dynamic>> _ngelxAndroidNativePost({
  required Uri hedef,
  required Uint8List bytes,
  required String token,
  required String contentType,
  required String legacyPath,
  required String asama,
}) async {
  if(!Platform.isAndroid)throw UnsupportedError('Android yerel medya isteği yalnızca Android için kullanılıyor.');
  try{
    final cevap=await _ngelxMedyaNativeKanal.invokeMapMethod<String,dynamic>('upload',{
      'url':hedef.toString(),
      'token':token,
      'contentType':contentType,
      'legacyPath':legacyPath,
      'bytes':bytes,
    }).timeout(const Duration(minutes:3));
    final status=(cevap?['status'] as num?)?.toInt()??0;
    final body=(cevap?['body']??'').toString();
    dynamic veri;
    try{veri=jsonDecode(body);}catch(_){veri=<String,dynamic>{'raw':body};}
    final map=veri is Map<String,dynamic>
        ?veri
        :veri is Map
            ?Map<String,dynamic>.from(veri)
            :<String,dynamic>{'raw':veri.toString()};
    if(status<200||status>=300){
      final detay=(map['message']??map['error']??map['raw']??'yanıt yok').toString();
      throw Exception('$asama | ${hedef.host}${hedef.path} | HTTP $status | $detay');
    }
    return map;
  }on PlatformException catch(e){
    throw Exception('$asama | ${hedef.host}${hedef.path} | ${e.code}: ${e.message??'bağlantı hatası'}');
  }on TimeoutException{
    throw Exception('$asama | ${hedef.host}${hedef.path} | zaman aşımı');
  }catch(e){
    final yazi=_ngelxKisaHata(e);
    if(yazi.startsWith(asama))rethrow;
    throw Exception('$asama | ${hedef.host}${hedef.path} | $yazi');
  }
}

Future<Map<String,dynamic>> _ngelxAndroidNativeGet({
  required Uri hedef,
  required String token,
  required String asama,
}) async {
  if(!Platform.isAndroid)throw UnsupportedError('Android yerel GET yalnızca Android için kullanılıyor.');
