    soket=await WebSocket.connect(
      hedef.toString(),
      headers:{
        HttpHeaders.authorizationHeader:'Bearer $token',
        'X-NgelX-Client':'android-websocket-file-$_ngelxMediaProtocolVersion',
        'X-NgelX-Filename':legacyPath,
      },
    ).timeout(const Duration(seconds:18));
    soket.pingInterval=const Duration(seconds:20);
    akis=StreamIterator<dynamic>(soket);

    final hazir=await _ngelxWsSonraki(akis,'ws ready',zamanAsimi:const Duration(seconds:20));
    if(hazir['type']!='ready'){
      throw Exception('ws ready | beklenmeyen yanıt: ${hazir['type']}');
    }

    const parcaBoyutu=5*1024*1024;
    final toplam=(size+parcaBoyutu-1)~/parcaBoyutu;
    raf=await yerel.open(mode:FileMode.read);
    var gonderilen=0;
    onProgress?.call(0,size);
    for(var i=0;i<toplam;i++){
      final kalan=size-gonderilen;
      final okunacak=kalan<parcaBoyutu?kalan:parcaBoyutu;
      final parca=await raf.read(okunacak);
      if(parca.length!=okunacak){
        throw Exception('ws part ${i+1}/$toplam | dosya okuma eksik');
      }
      soket.add(parca);
      final ack=await _ngelxWsSonraki(akis,'ws part ${i+1}/$toplam');
      if(ack['type']!='part'||(ack['partNumber'] as num?)?.toInt()!=i+1){
        throw Exception('ws part ${i+1}/$toplam | ACK uyuşmuyor');
      }
      gonderilen+=parca.length;
      onProgress?.call(gonderilen,size);
    }

    soket.add(jsonEncode({'type':'complete'}));
    final tamam=await _ngelxWsSonraki(
      akis,'ws complete',zamanAsimi:const Duration(minutes:2),
    );
    if(tamam['type']!='complete'){
      throw Exception('ws complete | beklenmeyen yanıt: ${tamam['type']}');
    }
    final url=(tamam['url']??'').toString();
    if(url.isEmpty)throw Exception('ws complete | sunucu medya URL döndürmedi.');
    return url;
  }on WebSocketException catch(e){
    throw Exception('ws connect | ${hedef.host} | ${e.message}');
  }on SocketException catch(e){
    throw Exception('ws socket | ${hedef.host} | ${e.message}');
  }catch(e){
    final yazi=_ngelxKisaHata(e);
    if(yazi.startsWith('ws '))rethrow;
    throw Exception('ws upload | ${hedef.host} | $yazi');
  }finally{
    try{await raf?.close();}catch(_){}
    try{await akis?.cancel();}catch(_){}
    try{await soket?.close();}catch(_){}
  }
}


Future<Map<String,dynamic>> _ngelxDirectR2Izin({
  required String api,
  required String kind,
  required String ext,
  required String contentType,
  required int size,
}) async {
  final user=FirebaseAuth.instance.currentUser;
  if(user==null)throw Exception('Medya yüklemek için giriş yapmalısın.');
  final token=await user.getIdToken(true);
  if(token==null||token.isEmpty)throw Exception('Güvenli medya oturumu oluşturulamadı.');

  final adaylar=<String>[];
  for(final raw in <String>[api,_ngelxMediaApiBackup]){
    final temiz=raw.trim().replaceAll(RegExp(r'/+$'),'');
    if(temiz.isNotEmpty&&!adaylar.contains(temiz))adaylar.add(temiz);
  }

  final hatalar=<String>[];
  for(final base in adaylar){
    final hedef=Uri.parse(base+'/upload/presign').replace(queryParameters:{
      'kind':kind,
      'ext':ext,
      'contentType':contentType,
      'size':size.toString(),
      'protocol':_ngelxMediaProtocolVersion,
    });

    for(var deneme=1;deneme<=2;deneme++){
      try{
        final cevap=await Dio(BaseOptions(
          connectTimeout:const Duration(seconds:15),
          receiveTimeout:const Duration(seconds:30),
          validateStatus:(s)=>s!=null,
        )).getUri(
          hedef,
          options:Options(
            responseType:ResponseType.json,
            headers:{
              HttpHeaders.authorizationHeader:'Bearer $token',
              'X-NgelX-Client':'direct-r2-$_ngelxMediaProtocolVersion',
              'Cache-Control':'no-cache',
            },
          ),
        );

        final status=cevap.statusCode??0;
        final veri=cevap.data;
        final map=veri is Map<String,dynamic>
            ?veri
            :veri is Map
                ?Map<String,dynamic>.from(veri)
                :<String,dynamic>{};

        if(status>=200&&status<300){
          final uploadUrl=(map['uploadUrl']??'').toString();
          final mediaUrl=(map['mediaUrl']??'').toString();
          if(uploadUrl.isEmpty||mediaUrl.isEmpty){
            hatalar.add('${hedef.host} deneme=$deneme | uploadUrl/mediaUrl eksik');
          }else{
            map['_presignHost']=hedef.host;
            map['_presignAttempt']=deneme;
            return map;
          }
        }else{
          final detay=(map['message']??map['error']??'yanıt yok').toString();
          hatalar.add('${hedef.host} deneme=$deneme | HTTP $status | $detay');
          // Kimlik doğrulama hatası endpoint değiştirerek düzelmez.
          if(status==401||status==403){
            throw Exception('presign HTTP $status | $detay');
          }
        }
      }on DioException catch(e){
        final durum=e.response?.statusCode;
        final govde=e.response?.data;
        hatalar.add('${hedef.host} deneme=$deneme dio | ${durum??'-'} | ${govde??e.message??e.type}');
        if(Platform.isAndroid){
          try{
            final map=await _ngelxAndroidNativeGet(
              hedef:hedef,
              token:token,
              asama:'presign native',
            );
            final uploadUrl=(map['uploadUrl']??'').toString();
            final mediaUrl=(map['mediaUrl']??'').toString();
            if(uploadUrl.isNotEmpty&&mediaUrl.isNotEmpty){
              map['_presignHost']=hedef.host;
              map['_presignAttempt']=deneme;
              map['_presignTransport']='android-native-httpurlconnection';
              return map;
            }
            hatalar.add('${hedef.host} deneme=$deneme native | uploadUrl/mediaUrl eksik');
          }catch(nativeHata){
            hatalar.add('${hedef.host} deneme=$deneme native | ${_ngelxKisaHata(nativeHata)}');
          }
        }
      }

      if(deneme<2){
        await Future<void>.delayed(Duration(milliseconds:350*deneme));
      }
    }
  }

  final detay=hatalar.isEmpty?'bilinmeyen bağlantı hatası':hatalar.join(' || ');
  throw Exception('presign bağlantı | primary+backup | $detay');
}

Future<String> _ngelxDirectR2BytesYukle({
  required String api,
  required Uint8List bytes,
  required String kind,
  required String ext,
  required String contentType,
  void Function(int sent,int total)? onProgress,
}) async {
  final izin=await _ngelxDirectR2Izin(
    api:api,kind:kind,ext:ext,contentType:contentType,size:bytes.length,
  );
  final upload=Uri.parse((izin['uploadUrl']??'').toString());
  final mediaUrl=(izin['mediaUrl']??'').toString();
  try{
    final cevap=await Dio(BaseOptions(
      connectTimeout:const Duration(seconds:20),
      sendTimeout:const Duration(minutes:5),
      receiveTimeout:const Duration(seconds:90),
      validateStatus:(s)=>s!=null,
    )).putUri(
      upload,
      data:bytes,
      onSendProgress:onProgress,
      options:Options(
        contentType:contentType,
        responseType:ResponseType.plain,
        headers:{HttpHeaders.contentLengthHeader:bytes.length},
      ),
    );
    final status=cevap.statusCode??0;
    if(status<200||status>=300){
      throw Exception('R2 PUT HTTP $status | ${cevap.data}');
    }
    return mediaUrl;
  }on DioException catch(e){
    final durum=e.response?.statusCode;
    final govde=e.response?.data;
    if(Platform.isAndroid){
      try{
        await _ngelxAndroidNativeR2Put(
          hedef:upload,
          contentType:contentType,
          bytes:bytes,
        );
        return mediaUrl;
      }catch(nativeHata){
        throw Exception('direct R2 PUT | ${upload.host} | dio=${durum??'-'} ${govde??e.message??e.type} | ${_ngelxKisaHata(nativeHata)}');
      }
    }
    throw Exception('direct R2 PUT | ${upload.host} | ${durum??'-'} | ${govde??e.message??e.type}');
  }
}

Future<String> _ngelxDirectR2DosyaYukle({
  required String api,
  required XFile dosya,
  required int size,
  required String kind,
  required String ext,
  required String contentType,
  void Function(int sent,int total)? onProgress,
}) async {
  final yerel=File(dosya.path);
  if(!await yerel.exists()){
    return _ngelxDirectR2BytesYukle(
      api:api,bytes:await dosya.readAsBytes(),kind:kind,ext:ext,
      contentType:contentType,onProgress:onProgress,
    );
  }

  final izin=await _ngelxDirectR2Izin(
    api:api,kind:kind,ext:ext,contentType:contentType,size:size,
  );
  final upload=Uri.parse((izin['uploadUrl']??'').toString());
  final mediaUrl=(izin['mediaUrl']??'').toString();
  try{
    final cevap=await Dio(BaseOptions(
      connectTimeout:const Duration(seconds:20),
      sendTimeout:const Duration(minutes:8),
      receiveTimeout:const Duration(seconds:90),
      validateStatus:(s)=>s!=null,
    )).putUri(
      upload,
      data:yerel.openRead(),
      onSendProgress:onProgress,
      options:Options(
        contentType:contentType,
        responseType:ResponseType.plain,
        headers:{HttpHeaders.contentLengthHeader:size},
      ),
    );
    final status=cevap.statusCode??0;
    if(status<200||status>=300){
      throw Exception('R2 PUT HTTP $status | ${cevap.data}');
    }
    return mediaUrl;
  }on DioException catch(e){
    final durum=e.response?.statusCode;
    final govde=e.response?.data;
    if(Platform.isAndroid){
      try{
        await _ngelxAndroidNativeR2Put(
          hedef:upload,
          contentType:contentType,
          filePath:dosya.path,
        );
        return mediaUrl;
      }catch(nativeHata){
        throw Exception('direct R2 PUT | ${upload.host} | dio=${durum??'-'} ${govde??e.message??e.type} | ${_ngelxKisaHata(nativeHata)}');
      }
    }
    throw Exception('direct R2 PUT | ${upload.host} | ${durum??'-'} | ${govde??e.message??e.type}');
  }
}

Future<String> ngelxMedyaYukleBytes({
  required Uint8List bytes,
  required String kind,
  required String ext,
  required String legacyPath,
  String? contentType,
  void Function(int sent,int total)? onProgress,
}) async {
  if(bytes.isEmpty)throw Exception('Seçilen medya boş.');
  final max=_ngelxMaksimumMedyaBoyutu(kind);
  if(bytes.length>max)throw Exception('Dosya boyutu bu medya türü için sınırı aşıyor.');
  final api=await ngelxMediaApiAdresi();
  final temizExt=_ngelxUzantiTemizle(ext);
  final tur=contentType??_ngelxContentType(temizExt);
  final hatalar=<String>[];

  try{
    return await _ngelxDirectR2BytesYukle(
      api:api,bytes:bytes,kind:kind,ext:temizExt,contentType:tur,
      onProgress:onProgress,
    );
  }catch(e){
    hatalar.add('direct: '+_ngelxKisaHata(e));
  }

  final adaylar=<String>[];
  for(final raw in <String>[api,_ngelxMediaApiBackup]){
    final temiz=raw.trim().replaceAll(RegExp(r'/+$'),'');
    if(temiz.isNotEmpty&&!adaylar.contains(temiz))adaylar.add(temiz);
  }

  for(final base in adaylar){
    try{
      return await _ngelxStandartBytesYukle(
        api:base,
        bytes:bytes,
        kind:kind,
        ext:temizExt,
        contentType:tur,
        legacyPath:legacyPath,
        onProgress:onProgress,
      );
    }catch(e){
      hatalar.add(base+': '+_ngelxKisaHata(e));
    }
  }

  if(Platform.isAndroid&&bytes.length<=10*1024*1024){
    for(final base in adaylar){
      try{
        return await _ngelxKucukMedyaYukleAndroid(
          api:base,
          bytes:bytes,
          kind:kind,
          ext:temizExt,
          contentType:tur,
          legacyPath:legacyPath,
          onProgress:onProgress,
        );
      }catch(e){
        hatalar.add('chunk '+base+': '+_ngelxKisaHata(e));
      }
    }
  }

  throw Exception('UPLOAD $_ngelxMediaProtocolVersion | kind=$kind | size=${bytes.length} | '+hatalar.join(' || '));
}

Future<String> ngelxMedyaYukleDosya({
  required XFile dosya,
  required String kind,
  required String ext,
  required String legacyPath,
  String? contentType,
  void Function(int sent,int total)? onProgress,
}) async {
  final boyut=await dosya.length();
  if(boyut<=0)throw Exception('Seçilen dosya boş görünüyor.');
  final max=_ngelxMaksimumMedyaBoyutu(kind);
  if(boyut>max)throw Exception('Dosya boyutu bu medya türü için sınırı aşıyor.');
  final api=await ngelxMediaApiAdresi();
  final temizExt=_ngelxUzantiTemizle(ext);
  final tur=contentType??_ngelxContentType(temizExt);
  final hatalar=<String>[];

  try{
    return await _ngelxDirectR2DosyaYukle(
      api:api,dosya:dosya,size:boyut,kind:kind,ext:temizExt,
      contentType:tur,onProgress:onProgress,
    );
  }catch(e){
    hatalar.add('direct: '+_ngelxKisaHata(e));
  }

  final adaylar=<String>[];
  for(final raw in <String>[api,_ngelxMediaApiBackup]){
    final temiz=raw.trim().replaceAll(RegExp(r'/+$'),'');
    if(temiz.isNotEmpty&&!adaylar.contains(temiz))adaylar.add(temiz);
  }

  for(final base in adaylar){
    try{
      return await _ngelxStandartDosyaYukle(
        api:base,
        dosya:dosya,
        size:boyut,
        kind:kind,
        ext:temizExt,
        contentType:tur,
        legacyPath:legacyPath,
        onProgress:onProgress,
      );
    }catch(e){
      hatalar.add(base+': '+_ngelxKisaHata(e));
    }
  }

  if(Platform.isAndroid){
    for(final base in adaylar){
      try{
        return await _ngelxWebSocketDosyaYukleAndroid(
          api:base,
          dosya:dosya,
          size:boyut,
          kind:kind,
          ext:temizExt,
          contentType:tur,
          legacyPath:legacyPath,
          onProgress:onProgress,
        );
      }catch(e){
        hatalar.add('ws '+base+': '+_ngelxKisaHata(e));
      }
    }
  }

  throw Exception('UPLOAD $_ngelxMediaProtocolVersion | kind=$kind | size=$boyut | '+hatalar.join(' || '));
}

Future<void> ngelxMedyaSil(String rawUrl) async {
  if (rawUrl.trim().isEmpty) return;
  final api = await ngelxMediaApiAdresi();
  if (api.isNotEmpty && rawUrl.startsWith('$api/media/')) {
    try {
      final user = FirebaseAuth.instance.currentUser;
      final token = await user?.getIdToken();
      if (token == null || token.isEmpty) return;
      final uri = Uri.parse(rawUrl);
      final key = Uri.decodeComponent(uri.path.substring('/media/'.length));
      await Dio().delete(
        '$api/object',
        queryParameters: {'key': key},
        options: Options(headers: {'Authorization': 'Bearer $token'}, sendTimeout: const Duration(seconds: 12), receiveTimeout: const Duration(seconds: 12)),
      );
      return;
    } catch (_) {
      return;
    }
  }
  // Eski Supabase bağlantıları yalnızca geçmiş içerikleri göstermek için tutulur.
  // Yeni medya R2'ye yazıldığı için eski depoya artık silme/yazma isteği gönderilmez.
}

