class CanliHazirlikPage extends StatefulWidget {
  const CanliHazirlikPage({super.key});
  @override
  State<CanliHazirlikPage> createState() => _CanliHazirlikPageState();
}

class _CanliHazirlikPageState extends State<CanliHazirlikPage> {
  final baslik = TextEditingController();
  bool baglaniyor = false;
  bool mikrofon = true;
  bool kamera = true;

  @override
  void dispose() {
    baslik.dispose();
    super.dispose();
  }

  Future<void> baslat() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null || user.isAnonymous || baglaniyor) return;
    if (baslik.text.trim().length < 3) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('En az 3 karakterlik yayın başlığı yaz.')));
      return;
    }
    setState(() => baglaniyor = true);
    lk.Room? oda;
    try {
      final odaAdi = 'ngelx_${user.uid}_${DateTime.now().millisecondsSinceEpoch}';
      final profil = await FirebaseFirestore.instance.collection('users').doc(user.uid).get();
      final ad = (profil.data()?['username'] ?? user.displayName ?? 'ngelx').toString();
      final kaynak = lk.DevelopmentTokenSource(id: liveKitTestSunucuId);
      final cevap = await kaynak.fetch(lk.TokenRequestOptions(
        roomName: odaAdi,
        participantIdentity: user.uid,
        participantName: ad,
        participantAttributes: const {'role': 'host'},
      ));
      oda = lk.Room(roomOptions: lk.RoomOptions(adaptiveStream: true, dynacast: true));
      await oda.connect(cevap.serverUrl, cevap.participantToken);
      final yerelKatilimci = oda.localParticipant;
      if (yerelKatilimci == null) throw Exception('Canlı yayın katılımcısı hazırlanamadı.');
      if (kamera) await yerelKatilimci.setCameraEnabled(true);
      if (mikrofon) await yerelKatilimci.setMicrophoneEnabled(true);
      final belge = await FirebaseFirestore.instance.collection('live_streams').add({
        'roomName': odaAdi,
        'ownerId': user.uid,
        'username': ad,
        'title': baslik.text.trim(),
        'active': true,
        'startedAt': FieldValue.serverTimestamp(),
      });
      if (!mounted) return;
      Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => CanliYayinPage(
        oda: oda!,
        belgeId: belge.id,
        baslik: baslik.text.trim(),
        yayinSahibi: true,
      )));
    } catch (e) {
      if (oda != null) {
        await oda.disconnect();
        await oda.dispose();
      }
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Yayın başlatılamadı: $e')));
    } finally {
      if (mounted) setState(() => baglaniyor = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Canlı yayın hazırla')),
      body: SafeArea(
        child: ListView(
          padding: const EdgeInsets.all(22),
          children: [
            Container(
              height: 290,
              decoration: BoxDecoration(
                gradient: const LinearGradient(begin: Alignment.topLeft, end: Alignment.bottomRight, colors: [Color(0xFF102C43), Color(0xFF301331)]),
                borderRadius: BorderRadius.circular(28),
              ),
              child: const Center(child: Icon(Icons.videocam_rounded, size: 82, color: Colors.white38)),
            ),
            const SizedBox(height: 20),
            TextField(controller: baslik, maxLength: 100, decoration: const InputDecoration(prefixIcon: Icon(Icons.edit_rounded), hintText: 'Yayın başlığı yaz')),
            SwitchListTile(value: kamera, onChanged: (v) => setState(() => kamera = v), secondary: const Icon(Icons.videocam_rounded), title: const Text('Kamera')),
            SwitchListTile(value: mikrofon, onChanged: (v) => setState(() => mikrofon = v), secondary: const Icon(Icons.mic_rounded), title: const Text('Mikrofon')),
            const ListTile(leading: Icon(Icons.public_rounded), title: Text('Herkese açık'), subtitle: Text('Keşfet bölümünde görünecek')),
            const SizedBox(height: 16),
            FilledButton.icon(
              style: FilledButton.styleFrom(backgroundColor: const Color(0xFFFF1744), minimumSize: const Size.fromHeight(58), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(22))),
              onPressed: baglaniyor ? null : baslat,
              icon: baglaniyor ? const SizedBox(width: 22, height: 22, child: CircularProgressIndicator(strokeWidth: 2)) : const Icon(Icons.sensors_rounded),
              label: Text(baglaniyor ? 'Bağlanıyor...' : 'Canlı yayına başla', style: const TextStyle(fontSize: 17, fontWeight: FontWeight.w800)),
            ),
            const SizedBox(height: 10),
            const Text('İlk kullanımda kamera ve mikrofon izni istenir.', textAlign: TextAlign.center, style: TextStyle(color: Colors.white54)),
          ],
        ),
      ),
    );
  }
}

class CanliYayinPage extends StatefulWidget {
  final lk.Room oda;
  final String belgeId;
  final String baslik;
  final bool yayinSahibi;
  const CanliYayinPage({super.key, required this.oda, required this.belgeId, required this.baslik, required this.yayinSahibi});
  @override
  State<CanliYayinPage> createState() => _CanliYayinPageState();
}

class _CanliYayinPageState extends State<CanliYayinPage> {
  final yorum = TextEditingController();
  Timer? sayac;
  int saniye = 0;
  bool mikrofonAcik = true;
  bool kameraAcik = true;
  bool kapatildi = false;
  bool kalpIsleniyor = false;

  @override
  void initState() {
    super.initState();
    widget.oda.addListener(_yenile);
    sayac = Timer.periodic(const Duration(seconds: 1), (_) {
      if (mounted) setState(() => saniye++);
    });
  }

  void _yenile() {
    if (mounted) setState(() {});
  }

  lk.VideoTrack? _goruntu() {
    if (widget.yayinSahibi) {
      for (final p in widget.oda.localParticipant?.videoTrackPublications ?? <lk.LocalTrackPublication>[]) {
        if (!p.muted && p.track is lk.VideoTrack) return p.track as lk.VideoTrack;
      }
    } else {
      for (final katilimci in widget.oda.remoteParticipants.values) {
        for (final p in katilimci.videoTrackPublications) {
          if (p.subscribed && !p.muted && p.track is lk.VideoTrack) return p.track as lk.VideoTrack;
        }
      }
    }
    return null;
  }

  Future<void> _bitir({bool geriDon = true}) async {
    if (kapatildi) return;
    kapatildi = true;
    if (widget.yayinSahibi) {
      await FirebaseFirestore.instance.collection('live_streams').doc(widget.belgeId).set({'active': false, 'endedAt': FieldValue.serverTimestamp()}, SetOptions(merge: true));
    }
    await widget.oda.disconnect();
    await widget.oda.dispose();
    if (geriDon && mounted) Navigator.pop(context);
  }

  Future<bool> _geri() async {
    if (widget.yayinSahibi) {
      final onay = await showDialog<bool>(context: context, builder: (_) => AlertDialog(
        title: const Text('Yayın bitsin mi?'),
        content: const Text('Canlı yayın tüm izleyiciler için kapanacak.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Devam et')),
          FilledButton(onPressed: () => Navigator.pop(context, true), child: const Text('Yayını bitir')),
        ],
      )) ?? false;
      if (!onay) return false;
    }
    await _bitir(geriDon: false);
    return true;
  }

  Future<void> _kalpDegistir() async {
    if(kalpIsleniyor)return;
    final user=FirebaseAuth.instance.currentUser;
    if(user==null)return;
    kalpIsleniyor=true;
    final ref=FirebaseFirestore.instance.collection('live_streams').doc(widget.belgeId).collection('reactions').doc(user.uid);
    try{
      final mevcut=await ref.get();
      if(mevcut.exists){
        await ref.delete();
      }else{
        await ref.set({'uid':user.uid,'type':'heart','createdAt':FieldValue.serverTimestamp()});
      }
    }catch(e){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Canlı yayın tepkisi gönderilemedi.')));
    }finally{
      kalpIsleniyor=false;
    }
  }

  Future<void> _yorumGonder() async {
    final metin = yorum.text.trim();
    final user = FirebaseAuth.instance.currentUser;
    if (metin.isEmpty || user == null) return;
    yorum.clear();
    final profil = await FirebaseFirestore.instance.collection('users').doc(user.uid).get();
    await FirebaseFirestore.instance.collection('live_streams').doc(widget.belgeId).collection('comments').add({
      'uid': user.uid,
      'username': (profil.data()?['username'] ?? 'ngelx').toString(),
      'text': metin,
      'createdAt': FieldValue.serverTimestamp(),
    });
  }

  @override
  void dispose() {
    sayac?.cancel();
    yorum.dispose();
    widget.oda.removeListener(_yenile);
    if (!kapatildi) _bitir(geriDon: false);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final track = _goruntu();
    final dakika = (saniye ~/ 60).toString().padLeft(2, '0');
    final sn = (saniye % 60).toString().padLeft(2, '0');
    return WillPopScope(
      onWillPop: _geri,
      child: Scaffold(
        backgroundColor: Colors.black,
        body: Stack(children: [
          Positioned.fill(child: track == null ? const Center(child: CircularProgressIndicator()) : lk.VideoTrackRenderer(track, fit: lk.VideoViewFit.cover)),
          Positioned.fill(child: DecoratedBox(decoration: BoxDecoration(gradient: LinearGradient(begin: Alignment.topCenter, end: Alignment.bottomCenter, colors: [Colors.black54, Colors.transparent, Colors.black.withOpacity(.8)])))),
          SafeArea(child: Padding(
            padding: const EdgeInsets.all(14),
            child: Column(children: [
              Row(children: [
                Container(padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8), decoration: BoxDecoration(color: const Color(0xFFFF1744), borderRadius: BorderRadius.circular(14)), child: const Text('● CANLI', style: TextStyle(fontWeight: FontWeight.w900))),
                const SizedBox(width: 8),
                Container(padding: const EdgeInsets.symmetric(horizontal: 11, vertical: 8), decoration: BoxDecoration(color: Colors.black45, borderRadius: BorderRadius.circular(14)), child: Text('$dakika:$sn')),
                const SizedBox(width: 8),
                Container(padding: const EdgeInsets.symmetric(horizontal: 11, vertical: 8), decoration: BoxDecoration(color: Colors.black45, borderRadius: BorderRadius.circular(14)), child: Text('👁 ${widget.oda.remoteParticipants.length}')),
                const Spacer(),
                IconButton(onPressed: () async { if (await _geri() && mounted) Navigator.pop(context); }, icon: const Icon(Icons.close_rounded, size: 31)),
              ]),
              const Spacer(),
              Align(alignment: Alignment.centerLeft, child: Container(
                constraints: const BoxConstraints(maxWidth: 330, maxHeight: 210),
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(color: Colors.black38, borderRadius: BorderRadius.circular(18)),
                child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                  stream: FirebaseFirestore.instance.collection('live_streams').doc(widget.belgeId).collection('comments').orderBy('createdAt', descending: true).limit(20).snapshots(),
                  builder: (_, snap) {
                    final yorumlar = snap.data?.docs ?? [];
                    if (yorumlar.isEmpty) return Text(widget.baslik, style: const TextStyle(fontWeight: FontWeight.w800));
                    return ListView.builder(reverse: true, shrinkWrap: true, itemCount: yorumlar.length, itemBuilder: (_, i) {
                      final y = yorumlar[i].data();
                      return Padding(padding: const EdgeInsets.symmetric(vertical: 3), child: Text('@${y['username'] ?? 'ngelx'}  ${y['text'] ?? ''}'));
                    });
                  },
                ),
              )),
              const SizedBox(height: 10),
              Row(children: [
                Expanded(child: TextField(controller: yorum, onSubmitted: (_) => _yorumGonder(), decoration: InputDecoration(hintText: 'Yorum yaz...', filled: true, fillColor: Colors.black54, suffixIcon: IconButton(onPressed: _yorumGonder, icon: const Icon(Icons.send_rounded))))),
                const SizedBox(width: 8),
                if (widget.yayinSahibi) ...[
                  IconButton.filled(onPressed: () async { mikrofonAcik = !mikrofonAcik; await widget.oda.localParticipant?.setMicrophoneEnabled(mikrofonAcik); if (mounted) setState(() {}); }, icon: Icon(mikrofonAcik ? Icons.mic : Icons.mic_off)),
                  const SizedBox(width: 6),
                  IconButton.filled(onPressed: () async { kameraAcik = !kameraAcik; await widget.oda.localParticipant?.setCameraEnabled(kameraAcik); if (mounted) setState(() {}); }, icon: Icon(kameraAcik ? Icons.videocam : Icons.videocam_off)),
                  const SizedBox(width: 6),
                  FilledButton(style: FilledButton.styleFrom(backgroundColor: const Color(0xFFFF1744)), onPressed: () async { if (await _geri() && mounted) Navigator.pop(context); }, child: const Text('Bitir')),
                ] else
                  StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(
                    stream:FirebaseFirestore.instance.collection('live_streams').doc(widget.belgeId).collection('reactions').snapshots(),
                    builder:(_,s){
                      final user=FirebaseAuth.instance.currentUser;
                      final benim=user!=null&&(s.data?.docs??[]).any((d)=>d.id==user.uid);
                      final sayi=s.data?.docs.length??0;
                      return FilledButton.tonalIcon(
                        onPressed:kalpIsleniyor?null:_kalpDegistir,
                        icon:Icon(benim?Icons.favorite_rounded:Icons.favorite_border_rounded,color:Colors.redAccent),
                        label:Text(sayi>0?'$sayi':'Beğen'),
                      );
                    },
                  ),
              ]),
            ]),
          )),
        ]),
      ),
    );
  }
}

class YuklePage extends StatefulWidget {
  const YuklePage({super.key});

  @override
  State<YuklePage> createState() => _YeniYuklePageState();
}

class _YeniYuklePageState extends State<YuklePage> {
  String tur='video';
  bool yukleniyor=false;
  bool indirmeyeIzin=true;
  bool yorumlaraIzin=true;
  bool yenidenPaylasimaIzin=true;
  String gizlilik='Herkes';
  String yorumKitlesi='Herkes';
  XFile? medya;
  List<XFile> medyalar=<XFile>[];
  String fotoEfekti='Yok';
  int fotoDonus=0;
  bool kareKirp=false,taslakVar=false;
  Timer? taslakZamanlayici;
  double yuklemeIlerlemesi=0;
  String yuklemeDurumu='';
  final aciklama=TextEditingController();
  final konum=TextEditingController();
  final etiketler=TextEditingController();

  @override
  void initState(){
    super.initState();
    aciklama.addListener(_taslakDegisti);konum.addListener(_taslakDegisti);etiketler.addListener(_taslakDegisti);
    unawaited(_taslagiYukle());
    unawaited(_kayipMedyaKurtar());
    final uid=FirebaseAuth.instance.currentUser?.uid;
    if(uid!=null){
      FirebaseFirestore.instance.collection('users').doc(uid).get().then((d){
        if(mounted)setState(()=>indirmeyeIzin=d.data()?['defaultAllowDownload']!=false);
      }).catchError((_){ });
    }
  }

  Future<void> _kayipMedyaKurtar()async{
    try{
      final sonuc=await ImagePicker().retrieveLostData();
      if(sonuc.isEmpty||!mounted)return;
      final dosyalar=sonuc.files;
      if(dosyalar==null||dosyalar.isEmpty)return;
      final dosya=dosyalar.first;
      final ad=dosya.name.toLowerCase();
      final video=ad.endsWith('.mp4')||ad.endsWith('.mov')||ad.endsWith('.m4v')||ad.endsWith('.webm');
      final secilenTur=video?'video':'photo';
      if(!await _medyaBoyutuUygun(dosya,secilenTur))return;
      if(mounted)setState((){tur=secilenTur;medya=dosya;medyalar=<XFile>[dosya];});_taslakDegisti();
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Seçtiğin medya geri yüklendi.')));
    }catch(_){}
  }

  @override
  void dispose(){taslakZamanlayici?.cancel();aciklama.dispose();konum.dispose();etiketler.dispose();super.dispose();}

  String get _taslakAnahtar=>'ngelx_create_draft_${FirebaseAuth.instance.currentUser?.uid??'local'}';
  void _taslakDegisti(){if(yukleniyor)return;taslakZamanlayici?.cancel();taslakZamanlayici=Timer(const Duration(milliseconds:500),()=>unawaited(_taslagiKaydet(sessiz:true)));}
  Future<void> _taslagiYukle()async{
    try{
      final h=await SharedPreferences.getInstance(),ham=h.getString(_taslakAnahtar);if(ham==null||ham.isEmpty)return;
      final v=Map<String,dynamic>.from(jsonDecode(ham) as Map),yollar=List<String>.from(v['mediaPaths']??const <String>[]),m=<XFile>[];
      for(final p in yollar){if(p.isNotEmpty&&await File(p).exists())m.add(XFile(p));}
      if(!mounted)return;
      setState((){tur=(v['type']??tur).toString();gizlilik=(v['privacy']??gizlilik).toString();yorumKitlesi=(v['commentAudience']??yorumKitlesi).toString();indirmeyeIzin=v['allowDownload']!=false;yorumlaraIzin=v['allowComments']!=false;yenidenPaylasimaIzin=v['allowReshare']!=false;fotoEfekti=(v['photoEffect']??'Yok').toString();fotoDonus=(v['photoRotation'] as num?)?.toInt()??0;kareKirp=v['photoSquareCrop']==true;medyalar=m;medya=m.isEmpty?null:m.first;taslakVar=true;});
      aciklama.text=(v['description']??'').toString();konum.text=(v['location']??'').toString();etiketler.text=(v['tags']??'').toString();
    }catch(_){}
  }
  Future<void> _taslagiKaydet({bool sessiz=false})async{
    final h=await SharedPreferences.getInstance(),bos=aciklama.text.trim().isEmpty&&konum.text.trim().isEmpty&&etiketler.text.trim().isEmpty&&medyalar.isEmpty&&medya==null;
    if(bos){await h.remove(_taslakAnahtar);if(mounted)setState(()=>taslakVar=false);return;}
    await h.setString(_taslakAnahtar,jsonEncode({'type':tur,'description':aciklama.text,'location':konum.text,'tags':etiketler.text,'privacy':gizlilik,'commentAudience':yorumKitlesi,'allowDownload':indirmeyeIzin,'allowComments':yorumlaraIzin,'allowReshare':yenidenPaylasimaIzin,'photoEffect':fotoEfekti,'photoRotation':fotoDonus,'photoSquareCrop':kareKirp,'mediaPaths':medyalar.isNotEmpty?medyalar.map((e)=>e.path).toList():(medya==null?<String>[]:<String>[medya!.path])}));
    if(mounted)setState(()=>taslakVar=true);if(!sessiz&&mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Taslak kaydedildi ✅')));
  }
  Future<void> _taslagiSil({bool mesaj=true})async{final h=await SharedPreferences.getInstance();await h.remove(_taslakAnahtar);if(mounted){setState(()=>taslakVar=false);if(mesaj)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Taslak temizlendi.')));}}

  void _turDegistir(String yeni){
    if(yukleniyor)return;
    setState((){tur=yeni;medya=null;medyalar=<XFile>[];fotoEfekti='Yok';fotoDonus=0;kareKirp=false;yuklemeIlerlemesi=0;yuklemeDurumu='';});
    _taslakDegisti();
  }

  String _dosyaHataMetni(Object e){
    if(e is PlatformException){
      if(e.code.contains('camera_access_denied'))return 'Kamera izni verilmedi.';
      if(e.code.contains('photo_access_denied'))return 'Galeri izni verilmedi.';
      return 'Dosya seçilemedi. Tekrar dene.';
    }
    if(e is FirebaseException&&e.code=='permission-denied'){
      return 'Paylaşım kaydedilemedi. Uygulama veri izinlerini kontrol et.';
    }
    return e.toString().replaceFirst('Exception: ','');
  }

  Future<bool> _medyaBoyutuUygun(XFile dosya,String secilenTur)async{
    final boyut=await dosya.length();
    final limit=secilenTur=='video'?50*1024*1024:10*1024*1024;
    if(boyut<=0){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Seçilen dosya boş görünüyor.')));
      return false;
    }
    if(boyut>limit){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(secilenTur=='video'?'Video en fazla 50 MB olabilir.':'Fotoğraf en fazla 10 MB olabilir.')));
      return false;
    }
    return true;
  }

  Future<void> medyaSec()async{
    if(yukleniyor||tur=='text')return;
    try{
      if(tur=='video'){final x=await ImagePicker().pickVideo(source:ImageSource.gallery);if(x==null||!mounted)return;if(!await _medyaBoyutuUygun(x,tur))return;setState((){medya=x;medyalar=<XFile>[x];});}
      else{final xs=await ImagePicker().pickMultiImage(imageQuality:84,maxWidth:1600,limit:10);if(xs.isEmpty||!mounted)return;final uygun=<XFile>[];for(final x in xs.take(10)){if(await _medyaBoyutuUygun(x,'photo'))uygun.add(x);}if(uygun.isEmpty||!mounted)return;setState((){medya=uygun.first;medyalar=uygun;});}
      _taslakDegisti();
    }catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(_dosyaHataMetni(e))));}
  }

  Future<void> kamerayiAc({required bool video})async{
    if(yukleniyor)return;
    try{
      final kameraIzni=await Permission.camera.request();
      if(!kameraIzni.isGranted){
        if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Kamerayı kullanmak için kamera izni vermelisin.')));
        return;
      }
      if(video)await Permission.microphone.request();
      final secilen=video
        ?await ImagePicker().pickVideo(source:ImageSource.camera,maxDuration:const Duration(minutes:10))
        :await ImagePicker().pickImage(source:ImageSource.camera,imageQuality:86,maxWidth:1600);
      if(secilen==null||!mounted)return;
      final secilenTur=video?'video':'photo';
      if(!await _medyaBoyutuUygun(secilen,secilenTur))return;
      if(mounted)setState((){tur=secilenTur;medya=secilen;medyalar=<XFile>[secilen];});_taslakDegisti();
    }catch(e){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(_dosyaHataMetni(e))));
    }
  }

  Future<void> kameraSecimi()async{
    if(yukleniyor)return;
    await showModalBottomSheet<void>(
      context:context,
      backgroundColor:Colors.white,
      shape:const RoundedRectangleBorder(borderRadius:BorderRadius.vertical(top:Radius.circular(28))),
      builder:(c)=>Theme(data:ThemeData.light(),child:SafeArea(child:Padding(
        padding:const EdgeInsets.all(22),
        child:Column(mainAxisSize:MainAxisSize.min,children:[
          Text(t('createWithCamera'),style:const TextStyle(color:Colors.black87,fontSize:21,fontWeight:FontWeight.w900)),
          const SizedBox(height:18),
          Row(children:[
            Expanded(child:_buyukSecenek(Icons.photo_camera_rounded,t('takePhoto'),(){Navigator.pop(c);unawaited(kamerayiAc(video:false));})),
            const SizedBox(width:12),
            Expanded(child:_buyukSecenek(Icons.videocam_rounded,t('takeVideo'),(){Navigator.pop(c);unawaited(kamerayiAc(video:true));})),
          ]),
        ]),
      ))),
    );
  }

  Future<void> hikayeSecimi()async{
    if(yukleniyor)return;
    await showModalBottomSheet<void>(
      context:context,
      backgroundColor:Colors.white,
      showDragHandle:true,
      shape:const RoundedRectangleBorder(borderRadius:BorderRadius.vertical(top:Radius.circular(28))),
      builder:(c)=>Theme(data:ThemeData.light(),child:SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:[
        ListTile(
          title:Text(t('createStory'),style:const TextStyle(fontSize:20,fontWeight:FontWeight.w900)),
          subtitle:const Text('Fotoğraf veya en fazla 30 saniyelik video • 24 saat görünür'),
        ),
        Row(children:[
          Expanded(child:ListTile(
            leading:const Icon(Icons.photo_library_outlined,color:mor),
            title:const Text('Galeriden fotoğraf'),
            onTap:(){Navigator.pop(c);unawaited(_hikayePaylas(ImageSource.gallery,video:false));},
          )),
          Expanded(child:ListTile(
            leading:const Icon(Icons.video_library_outlined,color:mor),
            title:const Text('Galeriden video'),
            onTap:(){Navigator.pop(c);unawaited(_hikayePaylas(ImageSource.gallery,video:true));},
          )),
        ]),
        Row(children:[
          Expanded(child:ListTile(
            leading:const Icon(Icons.photo_camera_outlined,color:mavi),
            title:const Text('Fotoğraf çek'),
            onTap:(){Navigator.pop(c);unawaited(_hikayePaylas(ImageSource.camera,video:false));},
          )),
          Expanded(child:ListTile(
            leading:const Icon(Icons.videocam_outlined,color:mavi),
            title:const Text('Video çek'),
            onTap:(){Navigator.pop(c);unawaited(_hikayePaylas(ImageSource.camera,video:true));},
          )),
        ]),
        const SizedBox(height:8),
      ]))),
    );
  }

  Future<void> _hikayePaylas(ImageSource kaynak,{required bool video})async{
    final user=FirebaseAuth.instance.currentUser;
    if(user==null||yukleniyor)return;
    try{
      if(kaynak==ImageSource.camera){
        final izin=await Permission.camera.request();
        if(!izin.isGranted){
          if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Hikâye çekmek için kamera izni vermelisin.')));
          return;
        }
        if(video){
          final mikrofon=await Permission.microphone.request();
          if(!mikrofon.isGranted){
            if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Videolu hikâye için mikrofon izni vermelisin.')));
            return;
          }
        }
      }

      final XFile? dosya=video
        ?await ImagePicker().pickVideo(source:kaynak,maxDuration:const Duration(seconds:30))
        :await ImagePicker().pickImage(source:kaynak,imageQuality:84,maxWidth:1600);
      if(dosya==null||!mounted)return;
      if(!await _medyaBoyutuUygun(dosya,video?'video':'photo'))return;

      setState((){
        yukleniyor=true;
        yuklemeDurumu=video?'Video hikâye yükleniyor...':'Hikâye yükleniyor...';
        yuklemeIlerlemesi=0;
      });

      final uzanti=dosya.name.contains('.')
        ?dosya.name.split('.').last.toLowerCase()
        :(video?'mp4':'jpg');
      final yol='stories/'+user.uid+'/'+DateTime.now().millisecondsSinceEpoch.toString()+'.'+uzanti;
      void ilerleme(int sent,int total){
        if(mounted&&total>0)setState(()=>yuklemeIlerlemesi=(sent/total).clamp(0.0,1.0).toDouble());
      }

      final url=video
        ?await ngelxMedyaYukleDosya(dosya:dosya,kind:'stories',ext:uzanti,legacyPath:yol,onProgress:ilerleme)
        :await ngelxMedyaYukleBytes(bytes:await dosya.readAsBytes(),kind:'stories',ext:uzanti,legacyPath:yol,onProgress:ilerleme);

      final profil=await FirebaseFirestore.instance.collection('users').doc(user.uid).get();
      final adi=(profil.data()?['username']??'ngelx').toString();
      final ref=await FirebaseFirestore.instance.collection('videos').add({
        'ownerId':user.uid,
        'username':adi,
        'type':'story',
        'storyMediaType':video?'video':'photo',
        'mediaUrl':url,
        'videoUrl':video?url:'',
        'createdAt':FieldValue.serverTimestamp(),
        'clientCreatedAt':Timestamp.now(),
        'expiresAt':Timestamp.fromDate(DateTime.now().add(const Duration(hours:24))),
        'replyCount':0,
        'reactionCount':0,
      });

      if(!mounted)return;
      final olusturma=Timestamp.now();
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content:Text(video?'Video hikâyen yayınlandı • 24 saat görünür.':'Hikâye yayınlandı • 24 saat görünür.'),
        action:SnackBarAction(
          label:'Görüntüle',
          onPressed:(){
            if(!mounted)return;
            Navigator.push(context,MaterialPageRoute(builder:(_)=>HikayeGosterPage(
              url:url,
              mediaType:video?'video':'photo',
              kullanici:'@'+adi,
              ownerUid:user.uid,
              storyId:ref.id,
              createdAt:olusturma,
              expiresAt:Timestamp.fromDate(DateTime.now().add(const Duration(hours:24))),
            )));
          },
        ),
      ));
    }catch(e){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Hikâye yayınlanamadı: '+_dosyaHataMetni(e))));
    }finally{
      if(mounted)setState((){
        yukleniyor=false;
        yuklemeDurumu='';
        yuklemeIlerlemesi=0;
      });
    }
  }

  Future<String> xDosyasiYukle(XFile dosya,String klasor)async{
    final user=FirebaseAuth.instance.currentUser;
    if(user==null)throw Exception('Paylaşmak için giriş yapmalısın.');
    final secilenTur=klasor=='videos'?'video':'photo';
    if(!await _medyaBoyutuUygun(dosya,secilenTur))throw Exception('Dosya boyutu uygun değil.');
    final uzanti=dosya.name.contains('.')?dosya.name.split('.').last.toLowerCase():(secilenTur=='video'?'mp4':'jpg');
    final yol='$klasor/${user.uid}/${DateTime.now().microsecondsSinceEpoch}.$uzanti';
    void ilerleme(int sent,int total){
      if(!mounted||total<=0)return;
      setState(()=>yuklemeIlerlemesi=(sent/total).clamp(0.0,1.0).toDouble());
    }
    if(secilenTur=='video'){
      return ngelxMedyaYukleDosya(
        dosya:dosya,
        kind:'videos',
        ext:uzanti,
        legacyPath:yol,
        onProgress:ilerleme,
      );
    }
    var b=await dosya.readAsBytes();var ext=uzanti;if(fotoEfekti!='Yok'||fotoDonus%4!=0||kareKirp){b=await ngelxFotoDuzenle(b,efekt:fotoEfekti,donus:fotoDonus,kareKirp:kareKirp);ext='png';}
    return ngelxMedyaYukleBytes(bytes:b,kind:'photos',ext:ext,legacyPath:yol.replaceFirst(RegExp(r'\.[^.]+$'),'.'+ext),onProgress:ilerleme);
  }

  Future<void> yayinla()async{
    final user=FirebaseAuth.instance.currentUser;
    if(user==null||yukleniyor)return;
    final metin=aciklama.text.trim();
    if(tur!='text'&&medya==null){
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Önce galeriden bir dosya seç veya kamerayı kullan.')));
      return;
    }
    if(tur=='text'&&metin.isEmpty){
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Paylaşmak istediğin yazıyı gir.')));
      return;
    }

    FocusScope.of(context).unfocus();
    setState((){
      yukleniyor=true;
      yuklemeIlerlemesi=0;
      yuklemeDurumu=tur=='text'?'Gönderi yayınlanıyor...':'Medya yükleniyor...';
    });

    try{
      String medyaUrl='';final medyaUrlListesi=<String>[];
      if(tur=='photo'&&medyalar.isNotEmpty){for(int i=0;i<medyalar.length;i++){if(mounted)setState(()=>yuklemeDurumu='Fotoğraf ${i+1}/${medyalar.length} yükleniyor...');medyaUrlListesi.add(await xDosyasiYukle(medyalar[i],'photos'));}medyaUrl=medyaUrlListesi.first;}
      else if(medya!=null){medyaUrl=await xDosyasiYukle(medya!,tur=='video'?'videos':'photos');medyaUrlListesi.add(medyaUrl);}
      if(mounted)setState(()=>yuklemeDurumu='Gönderi kaydediliyor...');

      final profil=await FirebaseFirestore.instance.collection('users').doc(user.uid).get().timeout(const Duration(seconds:10));
      final pv=profil.data()??<String,dynamic>{};
      final adi=(pv['username']??'ngelx').toString();
      await FirebaseFirestore.instance.collection('videos').add({
        'ownerId':user.uid,
        'username':adi,
        'type':tur,
        'videoUrl':tur=='video'?medyaUrl:'',
        'mediaUrl':medyaUrl,
        'mediaUrls':medyaUrlListesi,
        'mediaCount':medyaUrlListesi.length,
        'thumbnailUrl':'',
        'photoEffect':fotoEfekti,'photoRotation':fotoDonus,'photoSquareCrop':kareKirp,
        'description':metin,
        'allowDownload':indirmeyeIzin,
        'allowComments':yorumlaraIzin,
        'commentAudience':yorumlaraIzin?yorumKitlesi:'Kimse',
        'allowReshare':yenidenPaylasimaIzin,
        'privacy':gizlilik,
        'visibleTo':gizlilik=='Yakın arkadaşlar'?List<String>.from(pv['closeFriends']??const[]):<String>[],
        'hiddenFor':<String>[],
        'location':konum.text.trim(),
        'tags':etiketler.text.trim(),
        'likeCount':0,
        'commentCount':0,
        'shareCount':0,
        'viewCount':0,
        'createdAt':FieldValue.serverTimestamp(),
        'clientCreatedAt':Timestamp.now(),
      }).timeout(const Duration(seconds:12));

      if(!mounted)return;
      setState((){
        medya=null;medyalar=<XFile>[];fotoEfekti='Yok';fotoDonus=0;kareKirp=false;
        aciklama.clear();
        konum.clear();
        etiketler.clear();
