        yuklemeDurumu='';
      });
      unawaited(_taslagiSil(mesaj:false));
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content:const Text('Paylaşım yayınlandı ✅ Akışta ve profilinde görünecek.'),
        action:SnackBarAction(
          label:'Akışa git',
          onPressed:(){
            final ana=context.findAncestorStateOfType<_AnaEkranState>();
            if(ana!=null&&ana.mounted)ana.setState(()=>ana.secili=0);
          },
        ),
      ));
    }catch(e){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Yayınlanamadı: ${_dosyaHataMetni(e)}')));
    }finally{
      if(mounted)setState((){
        yukleniyor=false;
        yuklemeDurumu='';
        yuklemeIlerlemesi=0;
      });
    }
  }

