class ArsivSohbetlerPage extends StatefulWidget {
  final String uid;
  const ArsivSohbetlerPage({super.key, required this.uid});
  @override State<ArsivSohbetlerPage> createState() => _ArsivSohbetlerPageState();
}

class _ArsivSohbetlerPageState extends State<ArsivSohbetlerPage> {
  Future<List<String>> arsivGetir() async {
    final d = await FirebaseFirestore.instance.collection('users').doc(widget.uid).get();
    return List<String>.from(d.data()?['archivedChats'] ?? const []);
  }

  Future<void> geriAl(String id) async {
    await FirebaseFirestore.instance.collection('users').doc(widget.uid).set(
      {'archivedChats': FieldValue.arrayRemove([id])}, SetOptions(merge: true));
    if (mounted) setState(() {});
  }

  @override Widget build(BuildContext context) => Theme(
    data: ThemeData.light(),
    child: Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(title: Text(t('archivedChats'), style: const TextStyle(fontWeight: FontWeight.w900))),
      body: FutureBuilder<List<String>>(
        future: arsivGetir(),
        builder: (_, s) {
          final ids = s.data ?? [];
          if (s.connectionState == ConnectionState.waiting) return const Center(child: CircularProgressIndicator(color: mor));
          if (ids.isEmpty) return Center(child: Text(t('noArchivedChats'), style: const TextStyle(color: Colors.black54)));
          return ListView.separated(
            padding: const EdgeInsets.all(12), itemCount: ids.length,
            separatorBuilder: (_, __) => const Divider(),
            itemBuilder: (_, i) => FutureBuilder<DocumentSnapshot<Map<String,dynamic>>>(
              future: FirebaseFirestore.instance.collection('chats').doc(ids[i]).get(),
              builder: (_, c) {
                final v = c.data?.data() ?? <String,dynamic>{};
                final members = List<String>.from(v['members'] ?? const []);
                final grup = v['isGroup'] == true || members.length > 2;
                if (grup) return ListTile(
                  leading: const CircleAvatar(backgroundColor: Color(0xFFE9DDFF), child: Icon(Icons.groups, color: mor)),
                  title: Text((v['groupName'] ?? t('groupChat')).toString()), subtitle: Text((v['lastMessage'] ?? '').toString()),
                  trailing: IconButton(tooltip: t('unarchive'), onPressed: () => geriAl(ids[i]), icon: const Icon(Icons.unarchive_outlined, color: mor)),
                );
                final other = members.firstWhere((x) => x != widget.uid, orElse: () => widget.uid);
                return FutureBuilder<DocumentSnapshot<Map<String,dynamic>>>(
                  future: FirebaseFirestore.instance.collection('users').doc(other).get(),
                  builder: (_, u) {
                    final p = u.data?.data() ?? <String,dynamic>{};
                    final foto = (p['photoUrl'] ?? '').toString();
                    return ListTile(
                      leading: CircleAvatar(backgroundImage: foto.isEmpty ? null : CachedNetworkImageProvider(foto)),
                      title: Text((p['displayName'] ?? p['username'] ?? 'NgelX').toString(), style: const TextStyle(fontWeight: FontWeight.w800)),
                      subtitle: Text((v['lastMessage'] ?? '').toString()),
                      trailing: IconButton(tooltip: 'Arşivden çıkar', onPressed: () => geriAl(ids[i]), icon: const Icon(Icons.unarchive_outlined, color: mor)),
                    );
                  },
                );
              },
            ),
          );
        },
      ),
    ),
  );
}

class MesajIstekleriPage extends StatelessWidget {
  final String uid;
  const MesajIstekleriPage({super.key, required this.uid});
  @override Widget build(BuildContext context) => Theme(
    data: ThemeData.light(),
    child: Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(title: Text(t('messageRequests'), style: const TextStyle(fontWeight: FontWeight.w900))),
      body: FutureBuilder<DocumentSnapshot<Map<String,dynamic>>>(
        future: FirebaseFirestore.instance.collection('users').doc(uid).get(),
        builder: (_, me) {
          final arkadaslar = Set<String>.from(List<dynamic>.from(me.data?.data()?['friends'] ?? const []));
          return StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(
            stream: FirebaseFirestore.instance.collection('chats').where('members', arrayContains: uid).limit(60).snapshots(),
            builder: (_, s) {
              final docs = (s.data?.docs ?? []).where((d) {
                final v=d.data(), m=List<String>.from(v['members'] ?? const []);
                if(v['isGroup']==true || m.length!=2) return false;
                final other=m.firstWhere((x)=>x!=uid,orElse:()=>uid);
                final hedef=(v['requestRecipientUid']??uid).toString();
                return hedef==uid && !arkadaslar.contains(other) && v['requestAccepted_$uid']!=true && v['requestRejected_$uid']!=true;
              }).toList();
              if(docs.isEmpty) return Center(child: Text(t('noMessageRequests'), style: const TextStyle(color: Colors.black54)));
              return ListView.builder(
                padding: const EdgeInsets.all(12), itemCount: docs.length,
                itemBuilder: (_, i) {
                  final d=docs[i], v=d.data(), m=List<String>.from(v['members'] ?? const []);
                  final other=m.firstWhere((x)=>x!=uid,orElse:()=>uid);
                  return FutureBuilder<DocumentSnapshot<Map<String,dynamic>>>(
                    future: FirebaseFirestore.instance.collection('users').doc(other).get(),
                    builder: (_, u) {
                      final p=u.data?.data() ?? <String,dynamic>{}, foto=(p['photoUrl'] ?? '').toString();
                      final ad=(p['displayName'] ?? p['username'] ?? 'NgelX').toString();
                      Future<void> kabul()async{await d.reference.set({'requestAccepted_$uid':true,'requestRejected_$uid':false},SetOptions(merge:true));if(context.mounted)Navigator.push(context,MaterialPageRoute(builder:(_)=>SohbetPage(chatId:d.id,digerUid:other,ad:ad,foto:foto)));}
                      return Card(child: ListTile(
                        onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>MesajIstegiOnizlemePage(chatId:d.id,digerUid:other,ad:ad,foto:foto,uid:uid))),
                        leading: CircleAvatar(backgroundImage: foto.isEmpty ? null : CachedNetworkImageProvider(foto)),
                        title: Text(ad, style: const TextStyle(fontWeight: FontWeight.w800)),
                        subtitle: Text((v['lastMessage'] ?? t('messageRequest')).toString()),
                        trailing: TextButton(onPressed:kabul,child:Text(t('accept'))),
                      ));
                    },
                  );
                },
              );
            },
          );
        },
      ),
    ),
  );
}

class MesajIstegiOnizlemePage extends StatelessWidget{
  final String chatId,digerUid,ad,foto,uid;
  const MesajIstegiOnizlemePage({super.key,required this.chatId,required this.digerUid,required this.ad,required this.foto,required this.uid});
  @override Widget build(BuildContext context)=>Theme(data:ThemeData.light(),child:Scaffold(backgroundColor:Colors.white,appBar:AppBar(title:Text(ad)),body:Column(children:[
    Expanded(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('chats').doc(chatId).collection('messages').orderBy('createdAt').limitToLast(100).snapshots(),builder:(_,s)=>ListView(padding:const EdgeInsets.all(16),children:(s.data?.docs??[]).map((d){final v=d.data(),metin=(v['text']??'').toString(),photo=v['type']=='photo';return Align(alignment:v['senderId']==uid?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.symmetric(vertical:4),padding:EdgeInsets.all(photo?4:12),constraints:const BoxConstraints(maxWidth:280),decoration:BoxDecoration(color:const Color(0xFFF0F1F4),borderRadius:BorderRadius.circular(18)),child:photo?ClipRRect(borderRadius:BorderRadius.circular(15),child:Image.network((v['mediaUrl']??'').toString())):Text(metin)));}).toList()))),
    SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:OutlinedButton(onPressed:()async{await FirebaseFirestore.instance.collection('chats').doc(chatId).set({'requestRejected_$uid':true,'hiddenFor':FieldValue.arrayUnion([uid])},SetOptions(merge:true));if(context.mounted)Navigator.pop(context);},child:Text(t('reject')))),const SizedBox(width:8),Expanded(child:OutlinedButton(style:OutlinedButton.styleFrom(foregroundColor:Colors.red),onPressed:()async{await kullaniciyiEngelle(context,digerUid);await FirebaseFirestore.instance.collection('chats').doc(chatId).set({'requestRejected_$uid':true,'hiddenFor':FieldValue.arrayUnion([uid])},SetOptions(merge:true));if(context.mounted)Navigator.pop(context);},child:const Text('Engelle'))),const SizedBox(width:8),Expanded(child:FilledButton(onPressed:()async{await FirebaseFirestore.instance.collection('chats').doc(chatId).set({'requestAccepted_$uid':true},SetOptions(merge:true));if(context.mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>SohbetPage(chatId:chatId,digerUid:digerUid,ad:ad,foto:foto)));},child:Text(t('accept'))))]))),
  ])));
}



Future<void> ngelxGrupDavetMetaSenkronla(DocumentReference<Map<String,dynamic>> chatRef)async{
  try{
    final d=await chatRef.get();
    final v=d.data()??<String,dynamic>{};
    final code=(v['inviteCode']??'').toString().trim();
    if(code.isEmpty||v['isGroup']!=true||v['groupDeleted']==true)return;
    await FirebaseFirestore.instance.collection('group_invites').doc(code).set({
      'chatId':chatRef.id,
      'groupName':(v['groupName']??'Grup').toString(),
      'groupPhotoUrl':(v['groupPhotoUrl']??'').toString(),
      'joinApproval':v['joinApproval']==true,
      'admins':List<String>.from(v['admins']??const[]),
      'memberCount':List<String>.from(v['members']??const[]).length,
      'updatedAt':FieldValue.serverTimestamp(),
    },SetOptions(merge:true));
  }catch(_){}
}

class GrubaKatilPage extends StatefulWidget{
  const GrubaKatilPage({super.key});
  @override State<GrubaKatilPage> createState()=>_GrubaKatilPageState();
}
class _GrubaKatilPageState extends State<GrubaKatilPage>{
  final kod=TextEditingController();
  bool yukleniyor=false;

  @override void dispose(){kod.dispose();super.dispose();}

  String _koduAyikla(String ham){
    var t=ham.trim();
    if(t.isEmpty)return '';
    final uri=Uri.tryParse(t);
    if(uri!=null&&uri.pathSegments.isNotEmpty&&uri.pathSegments.contains('join')){
      final i=uri.pathSegments.indexOf('join');
      if(i>=0&&i+1<uri.pathSegments.length)return uri.pathSegments[i+1].trim();
    }
    if(t.contains('/join/'))t=t.split('/join/').last;
    if(t.contains('?'))t=t.split('?').first;
    return t.trim();
  }

  Future<void> katil()async{
    final me=FirebaseAuth.instance.currentUser?.uid;
    if(me==null||yukleniyor)return;
    final invite=_koduAyikla(kod.text);
    if(invite.isEmpty){
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Davet bağlantısı veya kodunu gir.')));
      return;
    }
    setState(()=>yukleniyor=true);
    try{
      final inviteRef=FirebaseFirestore.instance.collection('group_invites').doc(invite);
      final inviteSnap=await inviteRef.get().timeout(const Duration(seconds:10));
      if(!inviteSnap.exists){
        if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Davet bağlantısı geçersiz veya süresi dolmuş.')));
        return;
      }
      final iv=inviteSnap.data()??<String,dynamic>{};
      final chatId=(iv['chatId']??'').toString();
      if(chatId.isEmpty){
        if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Davet bağlantısı kullanılamıyor.')));
        return;
      }
      final chat=FirebaseFirestore.instance.collection('chats').doc(chatId);
      final ad=(iv['groupName']??'Grup').toString();
      final foto=(iv['groupPhotoUrl']??'').toString();

      // Zaten üyeyse Firestore bu belgeyi okumaya izin verir; değilse permission-denied
      // beklenen durumdur ve güvenli davet akışına devam edilir.
      try{
        final mevcut=await chat.get().timeout(const Duration(seconds:6));
        final members=List<String>.from(mevcut.data()?['members']??const[]);
        if(members.contains(me)){
          if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>GrupSohbetPage(chatId:chatId,ad:ad,foto:foto)));
          return;
        }
      }on FirebaseException catch(e){
        if(e.code!='permission-denied')rethrow;
      }

      final req=chat.collection('joinRequests').doc(me);
      final onayGerekli=iv['joinApproval']==true;
      await req.set({
        'uid':me,
        'status':onayGerekli?'pending':'autojoin',
        'inviteCode':invite,
        'createdAt':FieldValue.serverTimestamp(),
        'updatedAt':FieldValue.serverTimestamp(),
      },SetOptions(merge:true));

      if(onayGerekli){
        final admins=List<String>.from(iv['admins']??const[]);
        for(final admin in admins){
          if(admin==me)continue;
          unawaited(uygulamaBildirimiGonder(
            toUid:admin,fromUid:me,tur:'group',
            metin:'gruba katılma isteği gönderdi',
            belgeId:chatId,
          ).catchError((_){ }));
        }
        if(mounted){
          await showDialog<void>(
            context:context,
            builder:(c)=>AlertDialog(
              icon:const Icon(Icons.hourglass_top_rounded,color:ngelxGroupGreen,size:34),
              title:const Text('İstek gönderildi'),
              content:Text(ad+' grubunun yöneticileri isteğini inceleyecek.'),
              actions:[FilledButton(style:FilledButton.styleFrom(backgroundColor:ngelxGroupGreen),onPressed:()=>Navigator.pop(c),child:const Text('Tamam'))],
            ),
          );
          if(mounted)Navigator.pop(context);
        }
        return;
      }

      await chat.update({
        'members':FieldValue.arrayUnion([me]),
        'formerMembers':FieldValue.arrayRemove([me]),
        'hiddenFor':FieldValue.arrayRemove([me]),
        'updatedAt':FieldValue.serverTimestamp(),
      });
      try{
        final profil=await FirebaseFirestore.instance.collection('users').doc(me).get().timeout(const Duration(seconds:5));
        final pv=profil.data()??<String,dynamic>{};
        final isim=(pv['displayName']??pv['username']??'Bir üye').toString();
        final olay=isim+' gruba katıldı.';
        await chat.collection('messages').add({
          'senderId':me,
          'type':'system',
          'systemAction':'member_joined',
          'actorUid':me,
          'text':olay,
          'createdAt':FieldValue.serverTimestamp(),
        });
        await chat.set({'lastMessage':olay,'updatedAt':FieldValue.serverTimestamp()},SetOptions(merge:true));
      }catch(_){}
      await ngelxGrupDavetMetaSenkronla(chat);
      if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>GrupSohbetPage(chatId:chatId,ad:ad,foto:foto)));
    }on FirebaseException catch(e){
      if(mounted){
        final mesaj=e.code=='permission-denied'
          ?'Bu davet artık geçerli değil veya grup ayarları değişti.'
          :'Gruba katılma işlemi tamamlanamadı: '+e.code;
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(mesaj)));
      }
    }catch(_){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Gruba katılma işlemi tamamlanamadı.')));
    }finally{
      if(mounted)setState(()=>yukleniyor=false);
    }
  }

  @override Widget build(BuildContext context)=>Theme(
    data:ThemeData.light().copyWith(colorScheme:ColorScheme.fromSeed(seedColor:ngelxGroupGreen)),
    child:Scaffold(
      backgroundColor:Colors.white,
      appBar:AppBar(
        backgroundColor:Colors.transparent,surfaceTintColor:Colors.transparent,elevation:0,
        title:const Text('Gruba katıl',style:TextStyle(fontWeight:FontWeight.w900,color:ngelxPremiumInk)),
        flexibleSpace:Container(decoration:const BoxDecoration(gradient:LinearGradient(colors:[Color(0xFFFFFFFF),ngelxGroupGreenSoft]),borderRadius:BorderRadius.vertical(bottom:Radius.circular(24)))),
      ),
      body:ListView(
        padding:const EdgeInsets.fromLTRB(16,22,16,30),
        children:[
          NgelXPremiumCard(
            padding:const EdgeInsets.fromLTRB(18,24,18,22),
            child:Column(children:[
              Container(width:78,height:78,decoration:BoxDecoration(color:const Color(0xFFF0E8FF),borderRadius:BorderRadius.circular(26)),child:const Icon(Icons.group_add_rounded,color:ngelxPremiumPurple,size:40)),
              const SizedBox(height:15),
              const Text('Davetle gruba katıl',textAlign:TextAlign.center,style:TextStyle(color:ngelxPremiumInk,fontSize:21,fontWeight:FontWeight.w900)),
              const SizedBox(height:6),
              const Text('Sana gönderilen NgelX grup bağlantısını veya davet kodunu aşağıya yapıştır.',textAlign:TextAlign.center,style:TextStyle(color:ngelxPremiumMuted,fontSize:12,height:1.4,fontWeight:FontWeight.w600)),
            ]),
          ),
          const SizedBox(height:14),
          NgelXPremiumCard(
            padding:const EdgeInsets.all(14),
            child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
              const Text('Davet bağlantısı / kodu',style:TextStyle(color:ngelxPremiumInk,fontWeight:FontWeight.w900)),
              const SizedBox(height:10),
              TextField(
                controller:kod,
                textInputAction:TextInputAction.done,
                onSubmitted:(_)=>katil(),
                decoration:InputDecoration(
                  hintText:'ngelxsocial.com/join/...',
                  prefixIcon:const Icon(Icons.link_rounded,color:ngelxPremiumPurple),
                  suffixIcon:IconButton(
                    tooltip:'Yapıştır',
                    onPressed:()async{
                      final d=await Clipboard.getData(Clipboard.kTextPlain);
                      if(d?.text!=null)kod.text=d!.text!;
                    },
                    icon:const Icon(Icons.content_paste_rounded,color:ngelxPremiumPurple),
                  ),
                  filled:true,fillColor:const Color(0xFFF7F4F9),
                  border:OutlineInputBorder(borderRadius:BorderRadius.circular(18),borderSide:BorderSide.none),
                  enabledBorder:OutlineInputBorder(borderRadius:BorderRadius.circular(18),borderSide:const BorderSide(color:ngelxPremiumBorder)),
                ),
              ),
              const SizedBox(height:13),
              SizedBox(
                width:double.infinity,
                child:FilledButton.icon(
                  style:FilledButton.styleFrom(backgroundColor:ngelxPremiumPurple,padding:const EdgeInsets.symmetric(vertical:14),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(17))),
                  onPressed:yukleniyor?null:katil,
                  icon:yukleniyor?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2,color:Colors.white)):const Icon(Icons.login_rounded),
                  label:Text(yukleniyor?'Kontrol ediliyor...':'Gruba katıl',style:const TextStyle(fontWeight:FontWeight.w800)),
                ),
              ),
            ]),
          ),
          const SizedBox(height:14),
          const NgelXPremiumCard(
            padding:EdgeInsets.all(14),
            child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[
              Icon(Icons.verified_user_outlined,color:ngelxPremiumPurple),
              SizedBox(width:10),
              Expanded(child:Text('Grup yöneticisi onay istiyorsa önce katılma isteğin gönderilir. Onaylandığında bildirim alırsın.',style:TextStyle(color:ngelxPremiumMuted,fontSize:11.5,height:1.4,fontWeight:FontWeight.w600))),
            ]),
          ),
        ],
      ),
    ),
  );
}

class GrupOlusturPage extends StatefulWidget{const GrupOlusturPage({super.key});@override State<GrupOlusturPage> createState()=>_GrupOlusturPageState();}
class _GrupOlusturPageState extends State<GrupOlusturPage>{
  final ad=TextEditingController(),arama=TextEditingController();
  final Set<String> secilen={};
  final List<QueryDocumentSnapshot<Map<String,dynamic>>> adaylar=[];
  String sorgu='';
  int filtre=0;
  String? yuklemeHatasi;
  XFile? foto;
  bool kaydediliyor=false,izinlerYukleniyor=true;
  String? _olusturulanGrupId;

  @override void initState(){super.initState();izinliKisileriGetir();}
  @override void dispose(){ad.dispose();arama.dispose();super.dispose();}

  Future<void> izinliKisileriGetir()async{
    final u=FirebaseAuth.instance.currentUser;
    if(u==null){if(mounted)setState(()=>izinlerYukleniyor=false);return;}
    try{
      final d=await FirebaseFirestore.instance.collection('users').doc(u.uid).get().timeout(const Duration(seconds:8));
      final v=d.data()??<String,dynamic>{};
      final ids=<String>{...List<String>.from(v['following']??const[]),...List<String>.from(v['friends']??const[])}..remove(u.uid);
      final liste=ids.toList();
      final sorgular=<Future<QuerySnapshot<Map<String,dynamic>>>>[];
      for(int i=0;i<liste.length;i+=30){
        final son=(i+30<liste.length)?i+30:liste.length;
        final parca=liste.sublist(i,son);
        if(parca.isEmpty)continue;
        sorgular.add(FirebaseFirestore.instance.collection('users')
          .where(FieldPath.documentId,whereIn:parca)
          .get()
          .timeout(const Duration(seconds:8)));
      }
      final sonuclar=await Future.wait(sorgular).timeout(const Duration(seconds:12));
      final bulunan=<QueryDocumentSnapshot<Map<String,dynamic>>>[
        for(final q in sonuclar)...q.docs.where((x)=>x.data()['deactivated']!=true),
      ];
      if(mounted)setState((){adaylar..clear()..addAll(bulunan);izinlerYukleniyor=false;yuklemeHatasi=null;});
    }catch(e){
      if(mounted)setState((){izinlerYukleniyor=false;yuklemeHatasi='Kişiler yüklenemedi. İnternet bağlantını kontrol edip tekrar dene.';});
    }
  }
  Future<void> olustur()async{
    final u=FirebaseAuth.instance.currentUser;
    if(u==null||kaydediliyor)return;
    final grupAdi=ad.text.trim();
    if(grupAdi.length<2){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Grup adı en az 2 karakter olmalı.')));return;}
    if(grupAdi.length>16){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Grup adı en fazla 16 karakter olabilir.')));return;}
    if(secilen.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Grup için en az 1 kişi seç.')));return;}
    if(secilen.length>59){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Yönetici dahil grupta en fazla 60 üye olabilir.')));return;}
    setState(()=>kaydediliyor=true);
    try{
      String fotoUrl='';
      bool fotoAtlandi=false;
      if(foto!=null){
        try{
          final bytes=await foto!.readAsBytes().timeout(const Duration(seconds:8));
          final yol='groups/${u.uid}/${DateTime.now().millisecondsSinceEpoch}.jpg';
          fotoUrl=await ngelxMedyaYukleBytes(
            bytes: bytes,
            kind: 'groups',
            ext: 'jpg',
            legacyPath: yol,
          ).timeout(const Duration(seconds:75));
        }catch(_){
          fotoAtlandi=true;
          fotoUrl='';
        }
      }
      _olusturulanGrupId??=FirebaseFirestore.instance.collection('chats').doc().id;
      final ref=FirebaseFirestore.instance.collection('chats').doc(_olusturulanGrupId);
      await ref.set({
        'isGroup':true,
        'discoverable':true,
        'groupName':grupAdi,
        'groupPhotoUrl':fotoUrl,
        'members':[u.uid,...secilen],
        'admins':[u.uid],
        'moderators':<String>[],
        'createdBy':u.uid,
        'formerMembers':<String>[],
        'quickEmoji':'👍',
        'createdAt':FieldValue.serverTimestamp(),
        'updatedAt':FieldValue.serverTimestamp(),
        'lastMessage':'Grup oluşturuldu',
        'hiddenFor':<String>[],
        'maxMembers':60,
        'groupDescription':'',
        'onlyAdminsCanPost':false,
        'onlyAdminsCanAddMembers':false,
        'onlyAdminsCanEditGroup':true,
        'onlyAdminsCanPin':true,
        'onlyAdminsCanMentionAll':false,
        'newMembersSeeHistory':true,
        'joinApproval':false,
        'mutedFor':<String>[],
      }).timeout(const Duration(seconds:12));
      try{
        final profil=await FirebaseFirestore.instance.collection('users').doc(u.uid).get().timeout(const Duration(seconds:5));
        final pv=profil.data()??<String,dynamic>{};
        final ekleyen=(pv['displayName']??pv['username']??'Grup kurucusu').toString();
        final secilenAdlar=adaylar.where((d)=>secilen.contains(d.id)).map((d){
          final v=d.data();
          return (v['displayName']??v['username']??'Bir üye').toString();
        }).toList();
        String birlestir(List<String> adlar){
          if(adlar.isEmpty)return '';
          if(adlar.length==1)return adlar.first;
          if(adlar.length==2)return adlar.first+' ve '+adlar.last;
          return adlar.sublist(0,adlar.length-1).join(', ')+' ve '+adlar.last;
        }
        final gorunen=secilenAdlar.length<=4?secilenAdlar:secilenAdlar.take(4).toList();
        final devam=secilenAdlar.length>4?' ve '+(secilenAdlar.length-4).toString()+' kişi daha':'';
        final olay=ekleyen+', '+birlestir(gorunen)+devam+' adlı üyeleri gruba ekledi.';
        await ref.collection('messages').add({
          'senderId':u.uid,
          'type':'system',
          'systemAction':'member_added',
          'actorUid':u.uid,
          'targetUids':secilen.toList(),
          'text':olay,
          'createdAt':FieldValue.serverTimestamp(),
        });
        await ref.set({'lastMessage':olay,'updatedAt':FieldValue.serverTimestamp()},SetOptions(merge:true));
      }catch(_){}
      // Sohbet ekranını, grup belgesi Firestore'a kesin olarak yazıldıktan sonra aç.
      // Böylece messages alt koleksiyonu için üyelik kuralı ilk açılışta yarış durumuna girmez.
      if(mounted){
        if(fotoAtlandi)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Medya hizmeti kullanılamıyor. Grup fotoğrafsız oluşturuldu.')));
        Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>GrupSohbetPage(chatId:ref.id,ad:grupAdi,foto:fotoUrl)));
      }
    }catch(_){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Grup oluşturulamadı. Lütfen tekrar dene.')));
    }finally{
      if(mounted)setState(()=>kaydediliyor=false);
    }
  }
  @override Widget build(BuildContext context)=>Theme(
    data:ThemeData.light().copyWith(
      scaffoldBackgroundColor:const Color(0xFFFBF9FF),
      colorScheme:ColorScheme.fromSeed(seedColor:ngelxPremiumPurple),
    ),
    child:Scaffold(
      backgroundColor:const Color(0xFFFBF9FF),
      appBar:AppBar(
        toolbarHeight:64,
