class HikayeGosterPage extends StatefulWidget {
  final String url,kullanici,fotoUrl,ownerUid,storyId,mediaType;
  final dynamic createdAt,expiresAt;
  const HikayeGosterPage({
    super.key,
    required this.url,
    required this.kullanici,
    this.fotoUrl='',
    this.ownerUid='',
    this.storyId='',
    this.mediaType='photo',
    this.createdAt,
    this.expiresAt,
  });
  @override State<HikayeGosterPage> createState()=>_HikayeGosterPageState();
}

class _HikayeGosterPageState extends State<HikayeGosterPage> with SingleTickerProviderStateMixin {
  late final AnimationController sure;
  final cevap=TextEditingController();
  VideoPlayerController? videoKontrol;
  bool gonderiliyor=false,sessiz=false,videoHazir=false,videoHata=false;

  bool get videoMu{
    if(widget.mediaType=='video')return true;
    final temiz=widget.url.split('?').first.toLowerCase();
    return temiz.endsWith('.mp4')||temiz.endsWith('.mov')||temiz.endsWith('.m4v')||temiz.endsWith('.webm');
  }

  @override void initState(){
    super.initState();
    sure=AnimationController(vsync:this,duration:const Duration(seconds:7))
      ..addStatusListener((s){
        if(s==AnimationStatus.completed&&mounted)Navigator.pop(context);
      });
    if(videoMu){
      unawaited(_videoHazirla());
    }else{
      sure.forward();
    }
  }

  Future<void> _videoHazirla()async{
    try{
      final x=VideoPlayerController.networkUrl(Uri.parse(widget.url));
      videoKontrol=x;
      await x.initialize();
      if(!mounted)return;
      final d=x.value.duration;
      if(d.inMilliseconds>0){
        final ms=d.inMilliseconds.clamp(1000,30000);
        sure.duration=Duration(milliseconds:ms);
      }
      await x.setLooping(false);
      await x.setVolume(sessiz?0:1);
      setState(()=>videoHazir=true);
      sure.forward(from:0);
      await x.play();
    }catch(_){
      if(mounted){
        setState(()=>videoHata=true);
        sure.duration=const Duration(seconds:7);
        sure.forward(from:0);
      }
    }
  }

  void _duraklat(){
    sure.stop();
    if(videoMu&&videoKontrol?.value.isInitialized==true)unawaited(videoKontrol!.pause());
  }

  void _devam(){
    if(!mounted)return;
    sure.forward();
    if(videoMu&&videoKontrol?.value.isInitialized==true)unawaited(videoKontrol!.play());
  }

  Future<void> _sesDegistir()async{
    final yeni=!sessiz;
    setState(()=>sessiz=yeni);
    if(videoKontrol?.value.isInitialized==true)await videoKontrol!.setVolume(yeni?0:1);
  }

  @override void dispose(){
    cevap.dispose();
    sure.dispose();
    videoKontrol?.dispose();
    super.dispose();
  }

  String get zamanBilgisi{
    final olusma=widget.createdAt is Timestamp?(widget.createdAt as Timestamp).toDate():null;
    final bitis=widget.expiresAt is Timestamp?(widget.expiresAt as Timestamp).toDate():null;
    String baslangic='Az önce';
    if(olusma!=null){
      final fark=DateTime.now().difference(olusma);
      if(fark.inMinutes<60)baslangic='${fark.inMinutes.clamp(1,59)} dk önce';
      else if(fark.inHours<24)baslangic='${fark.inHours} sa önce';
      else baslangic='${fark.inDays} gün önce';
    }
    if(bitis==null)return baslangic;
    final kalan=bitis.difference(DateTime.now());
    if(kalan.isNegative)return '$baslangic • Süresi doldu';
    if(kalan.inHours>=1)return '$baslangic • ${kalan.inHours} sa kaldı';
    return '$baslangic • ${kalan.inMinutes.clamp(1,59)} dk kaldı';
  }

  Future<void> _yanitGonder(String ham,{bool tepki=false})async{
    final ben=FirebaseAuth.instance.currentUser;
    final hedef=widget.ownerUid.trim();
    final metin=ham.trim();
    if(ben==null||metin.isEmpty||gonderiliyor)return;
    if(hedef.isEmpty){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Hikâye sahibine ulaşılamadı.')));
      return;
    }
    if(hedef==ben.uid){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Bu kendi hikâyen.')));
      return;
    }
    setState(()=>gonderiliyor=true);
    _duraklat();
    try{
      final ids=<String>[ben.uid,hedef]..sort();
      final chatId=ids.join('_');
      final chat=FirebaseFirestore.instance.collection('chats').doc(chatId);
      final mesajRef=chat.collection('messages').doc();
      final batch=FirebaseFirestore.instance.batch();
      batch.set(chat,{
        'members':ids,
        'lastMessage':tepki?'$metin Hikâye tepkisi':'↩ Hikâye yanıtı: $metin',
        'updatedAt':FieldValue.serverTimestamp(),
        'unread_$hedef':FieldValue.increment(1),
      },SetOptions(merge:true));
      batch.set(mesajRef,{
        'senderId':ben.uid,
        'text':metin,
        'type':'story_reply',
        'storyId':widget.storyId,
        'storyUrl':widget.url,
        'storyOwnerId':hedef,
        'storyMediaType':widget.mediaType,
        'reaction':tepki,
        'createdAt':FieldValue.serverTimestamp(),
        'clientCreatedAt':Timestamp.now(),
      });
      if(widget.storyId.isNotEmpty){
        final story=FirebaseFirestore.instance.collection('videos').doc(widget.storyId);
        batch.set(story,{
          'replyCount':FieldValue.increment(1),
          if(tepki)'reactionCount':FieldValue.increment(1),
        },SetOptions(merge:true));
      }
      await batch.commit().timeout(const Duration(seconds:12));
      unawaited(uygulamaBildirimiGonder(
        toUid:hedef,fromUid:ben.uid,tur:'message',
        metin:tepki?'$metin hikâyene tepki verdi':'Hikâyene yanıt verdi',
        belgeId:chatId,
      ).catchError((_){ }));
      cevap.clear();
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(tepki?'Tepkin gönderildi.':'Yanıtın gönderildi.')));
    }catch(_){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Hikâye yanıtı gönderilemedi. Tekrar dene.')));
    }finally{
      if(mounted){
        setState(()=>gonderiliyor=false);
        _devam();
      }
    }
  }

  Widget _medya(){
    if(!videoMu){
      return CachedNetworkImage(
        imageUrl:widget.url,
        fit:BoxFit.contain,
        placeholder:(_,__)=>const Center(child:CircularProgressIndicator(color:Colors.white)),
        errorWidget:(_,__,___)=>const Center(child:Icon(Icons.broken_image_outlined,color:Colors.white54,size:60)),
      );
    }
    if(videoHata)return const Center(child:Column(mainAxisSize:MainAxisSize.min,children:[
      Icon(Icons.videocam_off_outlined,color:Colors.white54,size:62),
      SizedBox(height:10),
      Text('Video hikâye açılamadı',style:TextStyle(color:Colors.white70,fontWeight:FontWeight.w700)),
    ]));
    if(!videoHazir||videoKontrol==null)return const Center(child:CircularProgressIndicator(color:Colors.white));
    final oran=videoKontrol!.value.aspectRatio<=0?9/16:videoKontrol!.value.aspectRatio;
    return Center(child:AspectRatio(aspectRatio:oran,child:VideoPlayer(videoKontrol!)));
  }

  @override Widget build(BuildContext context){
    final benim=FirebaseAuth.instance.currentUser?.uid==widget.ownerUid;
    return Scaffold(
      backgroundColor:Colors.black,
      body:GestureDetector(
        onLongPressStart:(_)=>_duraklat(),
        onLongPressEnd:(_)=>_devam(),
        child:Stack(fit:StackFit.expand,children:[
          _medya(),
          Positioned.fill(child:IgnorePointer(child:DecoratedBox(decoration:BoxDecoration(
            gradient:LinearGradient(begin:Alignment.topCenter,end:Alignment.bottomCenter,colors:[Colors.black54,Colors.transparent,Colors.black54],stops:[0,.35,1]),
          )))),
          SafeArea(child:Padding(
            padding:const EdgeInsets.fromLTRB(14,10,14,12),
            child:Column(children:[
              AnimatedBuilder(animation:sure,builder:(_,__)=>ClipRRect(borderRadius:BorderRadius.circular(8),child:LinearProgressIndicator(value:sure.value,minHeight:3,color:Colors.white,backgroundColor:Colors.white24))),
              const SizedBox(height:10),
              Row(children:[
                CircleAvatar(radius:20,backgroundColor:mor,backgroundImage:widget.fotoUrl.isEmpty?null:CachedNetworkImageProvider(widget.fotoUrl),child:widget.fotoUrl.isEmpty?Text(widget.kullanici.replaceFirst('@','').isEmpty?'N':widget.kullanici.replaceFirst('@','')[0].toUpperCase()):null),
                const SizedBox(width:9),
                Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
                  Text(widget.kullanici,style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w900,fontSize:16)),
                  Text(zamanBilgisi,style:const TextStyle(color:Colors.white70,fontSize:12)),
                ])),
                if(videoMu)IconButton(
                  tooltip:sessiz?'Sesi aç':'Sesi kapat',
                  onPressed:_sesDegistir,
                  icon:Icon(sessiz?Icons.volume_off_rounded:Icons.volume_up_rounded,color:Colors.white,size:29),
                ),
                IconButton(tooltip:'Hikâye seçenekleri',onPressed:(){
                  _duraklat();
                  showModalBottomSheet<void>(
                    context:context,backgroundColor:Colors.white,showDragHandle:true,
                    builder:(c)=>SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:[
                      ListTile(leading:Icon(videoMu?Icons.videocam_outlined:Icons.image_outlined),title:Text(videoMu?'Video hikâye':'Fotoğraf hikâyesi'),subtitle:Text(zamanBilgisi)),
                      ListTile(leading:const Icon(Icons.close),title:const Text('Kapat'),onTap:()=>Navigator.pop(c)),
                    ])),
                  ).whenComplete(_devam);
                },icon:const Icon(Icons.more_horiz,color:Colors.white,size:28)),
                IconButton(onPressed:()=>Navigator.pop(context),icon:const Icon(Icons.close,color:Colors.white,size:32)),
              ]),
              const Spacer(),
              if(!benim&&widget.ownerUid.isNotEmpty) ...[
                Row(children:[
                  Expanded(child:TextField(
                    controller:cevap,
                    onTap:_duraklat,
                    onSubmitted:(v)=>_yanitGonder(v),
                    style:const TextStyle(color:Colors.white),
                    decoration:InputDecoration(
                      hintText:'Mesaj gönder',
                      hintStyle:const TextStyle(color:Colors.white70),
                      filled:true,fillColor:Colors.black45,
                      contentPadding:const EdgeInsets.symmetric(horizontal:18,vertical:12),
                      border:OutlineInputBorder(borderRadius:BorderRadius.circular(28),borderSide:BorderSide.none),
                      suffixIcon:gonderiliyor?const Padding(padding:EdgeInsets.all(13),child:SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2,color:Colors.white))):IconButton(onPressed:()=>_yanitGonder(cevap.text),icon:const Icon(Icons.send_rounded,color:Colors.white)),
                    ),
                  )),
                  const SizedBox(width:8),
                  for(final e in const ['❤️','😂','😮'])
                    InkWell(
                      onTap:gonderiliyor?null:()=>_yanitGonder(e,tepki:true),
                      borderRadius:BorderRadius.circular(28),
                      child:Padding(padding:const EdgeInsets.symmetric(horizontal:7,vertical:8),child:Text(e,style:const TextStyle(fontSize:29))),
                    ),
                ]),
              ] else
                Container(
                  padding:const EdgeInsets.symmetric(horizontal:14,vertical:9),
                  decoration:BoxDecoration(color:Colors.black45,borderRadius:BorderRadius.circular(18)),
                  child:Text(videoMu?'Video hikâyen':'Hikâyen',style:const TextStyle(color:Colors.white70,fontWeight:FontWeight.w700)),
                ),
            ]),
          )),
        ]),
      ),
    );
  }
}

class HesapDegistirPage extends StatefulWidget {
  const HesapDegistirPage({super.key});
  @override State<HesapDegistirPage> createState()=>_HesapDegistirPageState();
}

class _HesapDegistirPageState extends State<HesapDegistirPage> {
  final guvenliHafiza=const FlutterSecureStorage();
  List<String> hesaplar=<String>[];
  bool yukleniyor=true;
  bool islem=false;

  String sifreAnahtari(String adres)=>'ngelx_sifre_'+adres.trim().toLowerCase();
  String uidAnahtari(String adres)=>'hatirlanan_uid_'+adres.trim().toLowerCase();

  @override void initState(){super.initState();_yukle();}

  Future<void> _yukle()async{
    final h=await SharedPreferences.getInstance();
    final ham=h.getStringList('hatirlanan_epostalar')??<String>[];
    final tek=<String>[];
    for(final e in ham){
      final temiz=e.trim();
      if(temiz.isNotEmpty&&!tek.any((x)=>x.toLowerCase()==temiz.toLowerCase()))tek.add(temiz);
    }
    final aktif=FirebaseAuth.instance.currentUser;
    final aktifEmail=aktif?.email?.trim()??'';
    if(aktifEmail.isNotEmpty){
      tek.removeWhere((x)=>x.toLowerCase()==aktifEmail.toLowerCase());
      tek.insert(0,aktifEmail);
      await h.setString(uidAnahtari(aktifEmail),aktif!.uid);
    }
    if(tek.length>5)tek.removeRange(5,tek.length);
    await h.setStringList('hatirlanan_epostalar',tek);
    if(aktifEmail.isNotEmpty)await h.setString('hatirlanan_eposta',aktifEmail);
    if(mounted)setState((){hesaplar=tek;yukleniyor=false;});
  }

  Future<Map<String,dynamic>> _profil(String email)async{
    final h=await SharedPreferences.getInstance();
    final uid=h.getString(uidAnahtari(email))??'';
    if(uid.isEmpty)return <String,dynamic>{'email':email};
    try{
      final d=await FirebaseFirestore.instance.collection('users').doc(uid).get().timeout(const Duration(seconds:6));
      final veri=d.data()??<String,dynamic>{};
      return <String,dynamic>{'email':email,'uid':uid,...veri};
    }catch(_){
      return <String,dynamic>{'email':email,'uid':uid};
    }
  }

  Future<String?> _sifreSor(String email)async{
    final c=TextEditingController();
    bool gizli=true;
    final sonuc=await showModalBottomSheet<String>(
      context:context,isScrollControlled:true,backgroundColor:Colors.white,
      shape:const RoundedRectangleBorder(borderRadius:BorderRadius.vertical(top:Radius.circular(28))),
      builder:(ctx)=>Theme(data:ThemeData.light(),child:StatefulBuilder(builder:(ctx,setP)=>Padding(
        padding:EdgeInsets.fromLTRB(20,22,20,MediaQuery.of(ctx).viewInsets.bottom+24),
        child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[
          const Text('Hesaba geç',style:TextStyle(fontSize:22,fontWeight:FontWeight.w900)),
          const SizedBox(height:5),
          Text(email,style:const TextStyle(color:Colors.black54)),
          const SizedBox(height:16),
          TextField(
            controller:c,obscureText:gizli,autofocus:true,
            decoration:InputDecoration(
              labelText:'Şifre',prefixIcon:const Icon(Icons.lock_outline_rounded),
              suffixIcon:IconButton(onPressed:()=>setP(()=>gizli=!gizli),icon:Icon(gizli?Icons.visibility_off_outlined:Icons.visibility_outlined)),
            ),
          ),
          const SizedBox(height:16),
          FilledButton(
            style:FilledButton.styleFrom(backgroundColor:ngelxPremiumPurple,padding:const EdgeInsets.symmetric(vertical:14)),
            onPressed:()=>Navigator.pop(ctx,c.text),
            child:const Text('Devam et',style:TextStyle(fontWeight:FontWeight.w800)),
          ),
        ]),
      ))),
    );
    c.dispose();
    return sonuc;
  }

  Future<void> _giris(String email,{String? parola})async{
    if(islem)return;
    final mevcut=FirebaseAuth.instance.currentUser?.email?.toLowerCase();
    if(mevcut==email.toLowerCase()){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Bu hesap zaten açık.')));
      return;
    }
    var sifre=parola??await guvenliHafiza.read(key:sifreAnahtari(email));
    sifre=sifre?.trim();
    if(sifre==null||sifre.isEmpty)sifre=await _sifreSor(email);
    if(sifre==null||sifre.length<6)return;
    setState(()=>islem=true);
    try{
      final sonuc=await FirebaseAuth.instance.signInWithEmailAndPassword(email:email.trim(),password:sifre);
      await sonuc.user?.reload();
      final user=FirebaseAuth.instance.currentUser;
      if(user==null)throw Exception('Oturum açılamadı.');
      if(user.emailVerified!=true){
        await user.sendEmailVerification();
        throw Exception('Bu hesabın e-postası henüz doğrulanmamış. Doğrulama bağlantısı gönderildi.');
      }
      final h=await SharedPreferences.getInstance();
      hesaplar.removeWhere((x)=>x.toLowerCase()==email.toLowerCase());
      hesaplar.insert(0,email.trim());
      if(hesaplar.length>5)hesaplar=hesaplar.take(5).toList();
      await h.setStringList('hatirlanan_epostalar',hesaplar);
      await h.setString('hatirlanan_eposta',email.trim());
      await h.setString(uidAnahtari(email),user.uid);
      await guvenliHafiza.write(key:sifreAnahtari(email),value:sifre);
      unawaited(girisKaydiEkle(user));
      if(!mounted)return;
      Navigator.of(context).pushAndRemoveUntil(MaterialPageRoute(builder:(_)=>const AnaEkran()),(_)=>false);
    }on FirebaseAuthException catch(e){
      String mesaj;
      if(e.code=='wrong-password'||e.code=='invalid-credential'){
        mesaj='E-posta veya şifre hatalı.';
      }else if(e.code=='user-not-found'){
        mesaj='Bu e-postayla kayıtlı hesap bulunamadı.';
      }else if(e.code=='too-many-requests'){
        mesaj='Çok fazla deneme yapıldı. Biraz sonra tekrar dene.';
      }else{
        mesaj='Hesaba geçilemedi: '+(e.message??e.code);
      }
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(mesaj)));
    }catch(e){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));
    }finally{
      if(mounted)setState(()=>islem=false);
    }
  }

  Future<void> _hesapEkle()async{
    if(hesaplar.length>=5){
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('En fazla 5 hesap ekleyebilirsin.')));
      return;
    }
    final e=TextEditingController(),p=TextEditingController();
    bool gizli=true;
    final sonuc=await showModalBottomSheet<Map<String,String>>(
      context:context,isScrollControlled:true,backgroundColor:Colors.white,
      shape:const RoundedRectangleBorder(borderRadius:BorderRadius.vertical(top:Radius.circular(28))),
      builder:(ctx)=>Theme(data:ThemeData.light(),child:StatefulBuilder(builder:(ctx,setP)=>Padding(
        padding:EdgeInsets.fromLTRB(20,22,20,MediaQuery.of(ctx).viewInsets.bottom+24),
        child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[
          const Text('Hesap ekle',style:TextStyle(fontSize:22,fontWeight:FontWeight.w900)),
          const SizedBox(height:5),
          Text(hesaplar.length.toString()+'/5 hesap kullanılıyor',style:const TextStyle(color:Colors.black54)),
          const SizedBox(height:16),
          TextField(controller:e,keyboardType:TextInputType.emailAddress,autocorrect:false,decoration:const InputDecoration(labelText:'E-posta adresi',prefixIcon:Icon(Icons.alternate_email_rounded))),
          const SizedBox(height:10),
          TextField(controller:p,obscureText:gizli,decoration:InputDecoration(labelText:'Şifre',prefixIcon:const Icon(Icons.lock_outline_rounded),suffixIcon:IconButton(onPressed:()=>setP(()=>gizli=!gizli),icon:Icon(gizli?Icons.visibility_off_outlined:Icons.visibility_outlined)))),
          const SizedBox(height:16),
          FilledButton(
            style:FilledButton.styleFrom(backgroundColor:ngelxPremiumPurple,padding:const EdgeInsets.symmetric(vertical:14)),
            onPressed:(){
              final email=e.text.trim(),sifre=p.text;
              if(!email.contains('@')||sifre.length<6){
                ScaffoldMessenger.of(ctx).showSnackBar(const SnackBar(content:Text('Geçerli e-posta ve şifre gir.')));
                return;
              }
              Navigator.pop(ctx,{'email':email,'password':sifre});
            },
            child:const Text('Hesabı ekle ve geç',style:TextStyle(fontWeight:FontWeight.w800)),
          ),
        ]),
      ))),
    );
    e.dispose();p.dispose();
    if(sonuc==null||!mounted)return;
    await _giris(sonuc['email']??'',parola:sonuc['password']??'');
  }

  Future<void> _kaldir(String email)async{
    final aktif=FirebaseAuth.instance.currentUser?.email?.toLowerCase()??'';
    if(aktif==email.toLowerCase()){
      if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Açık olan hesabı cihazdan kaldıramazsın. Önce başka hesaba geç.')));
      return;
    }
    final ok=await showDialog<bool>(context:context,builder:(ctx)=>Theme(data:ThemeData.light(),child:AlertDialog(
      backgroundColor:Colors.white,
      title:const Text('Bu hesabı cihazdan kaldır?'),
      content:Text(email+' için kaydedilen hızlı giriş bilgileri silinecek. Hesabın NgelX’ten silinmez.'),
      actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Cihazdan kaldır'))],
    )))??false;
    if(!ok)return;
    final h=await SharedPreferences.getInstance();
    hesaplar.removeWhere((x)=>x.toLowerCase()==email.toLowerCase());
    await h.setStringList('hatirlanan_epostalar',hesaplar);
    await h.remove(uidAnahtari(email));
    await guvenliHafiza.delete(key:sifreAnahtari(email));
    if((h.getString('hatirlanan_eposta')??'').toLowerCase()==email.toLowerCase()){
      if(hesaplar.isEmpty){await h.remove('hatirlanan_eposta');}else{await h.setString('hatirlanan_eposta',hesaplar.first);}
    }
    if(mounted)setState((){});
  }

  @override Widget build(BuildContext context){
    final aktif=FirebaseAuth.instance.currentUser?.email?.toLowerCase()??'';
    return Theme(data:ThemeData.light(),child:Scaffold(
      backgroundColor:Colors.white,
      appBar:AppBar(backgroundColor:Colors.white,surfaceTintColor:Colors.white,elevation:0,title:Text(t('switchAccount'),style:TextStyle(fontWeight:FontWeight.w900))),
      body:yukleniyor?const Center(child:CircularProgressIndicator(color:mor)):ListView(
        padding:const EdgeInsets.fromLTRB(16,10,16,30),
        children:[
          NgelXPremiumCard(
            color:const Color(0xFFF8F5FF),
            child:Row(children:[
              const Icon(Icons.switch_account_rounded,color:ngelxPremiumPurple,size:30),
              const SizedBox(width:12),
              const Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
                Text('NgelX hesapların',style:TextStyle(fontWeight:FontWeight.w900,fontSize:17)),
                SizedBox(height:3),
                Text('Bu cihazda en fazla 5 hesap arasında hızlı geçiş yapabilirsin.',style:TextStyle(color:ngelxPremiumMuted,fontSize:12,height:1.3)),
              ])),
              Text(hesaplar.length.toString()+'/5',style:const TextStyle(color:ngelxPremiumPurple,fontWeight:FontWeight.w900)),
            ]),
          ),
          const SizedBox(height:14),
          ...hesaplar.map((email)=>FutureBuilder<Map<String,dynamic>>(
            future:_profil(email),
            builder:(_,s){
              final v=s.data??<String,dynamic>{};
              final foto=(v['photoUrl']??'').toString();
              final ad=(v['displayName']??v['username']??email).toString();
              final bu=aktif==email.toLowerCase();
              return NgelXPremiumCard(
                margin:const EdgeInsets.only(bottom:10),
                padding:const EdgeInsets.symmetric(horizontal:12,vertical:10),
                child:Row(children:[
                  CircleAvatar(
                    radius:23,backgroundColor:const Color(0xFFF0E8FF),
                    backgroundImage:foto.isEmpty?null:CachedNetworkImageProvider(foto),
                    child:foto.isEmpty?Text(ad.isEmpty?'N':ad[0].toUpperCase(),style:const TextStyle(color:ngelxPremiumPurple,fontWeight:FontWeight.w900)):null,
                  ),
                  const SizedBox(width:11),
                  Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
                    Row(children:[
                      Flexible(child:Text(ad,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontWeight:FontWeight.w900))),
                      if(v['verified']==true)...[const SizedBox(width:4),const Icon(Icons.verified_rounded,color:Color(0xFF1687FF),size:17)],
                    ]),
                    Text(email,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(color:ngelxPremiumMuted,fontSize:11.5)),
                  ])),
                  if(bu)
                    Container(padding:const EdgeInsets.symmetric(horizontal:9,vertical:5),decoration:BoxDecoration(color:const Color(0xFFE7F9EF),borderRadius:BorderRadius.circular(12)),child:const Text('Bu hesap',style:TextStyle(color:Color(0xFF0A8F48),fontSize:10,fontWeight:FontWeight.w900)))
                  else
                    TextButton(onPressed:islem?null:()=>_giris(email),child:const Text('Geç')),
                  PopupMenuButton<String>(
                    enabled:!islem,
                    onSelected:(x){if(x=='remove')_kaldir(email);},
                    itemBuilder:(_)=>const [PopupMenuItem(value:'remove',child:Text('Bu cihazdan kaldır'))],
                  ),
                ]),
              );
            },
          )),
          const SizedBox(height:4),
          OutlinedButton.icon(
            onPressed:islem?null:_hesapEkle,
            style:OutlinedButton.styleFrom(padding:const EdgeInsets.symmetric(vertical:14),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(18))),
            icon:const Icon(Icons.add_circle_outline_rounded),
            label:Text(hesaplar.length>=5?'5 hesap sınırına ulaştın':'Hesap ekle',style:const TextStyle(fontWeight:FontWeight.w800)),
          ),
          if(islem)...[
            const SizedBox(height:18),
            const Center(child:CircularProgressIndicator(color:ngelxPremiumPurple)),
          ],
        ],
      ),
    ));
  }
}


